window.__contenido("snowflake-paso-a-paso", {"snowflake-paso-a-paso-que-es-snowflake-y-snowsight":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 En palabras simples</div>\n\n<p>Una base tradicional es como un auto: el motor y el baúl vienen juntos, y si necesitas más motor, cambias el auto entero. <strong>Snowflake separa el baúl (los datos) del motor (el cómputo)</strong>: los datos se guardan una sola vez y prendes los motores que necesites - uno chico para los analistas, uno grande para la carga de la noche - y los apagas cuando no se usan.</p>\n</div>\n\n\n<h2>Paso 1 — Las tres capas</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Capa</th>\n<th>Qué hace</th>\n<th>Se paga</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Almacenamiento</strong></td>\n<td>Guarda las tablas comprimidas en micro-particiones, en la nube que elijas (AWS, Azure o GCP)</td>\n<td>Por TB al mes</td>\n</tr>\n<tr>\n<td><strong>Cómputo (warehouses virtuales)</strong></td>\n<td>Ejecuta las consultas. Se prende, se apaga y cambia de tamaño en segundos</td>\n<td>Créditos por segundo mientras está encendido</td>\n</tr>\n<tr>\n<td><strong>Servicios en la nube</strong></td>\n<td>Seguridad, metadatos, optimizador, caché de resultados</td>\n<td>Incluido hasta cierto uso</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — Los objetos</h2>\n<figure class=\"diagrama\" data-spec=\"{&quot;titulo&quot;:&quot;Los objetos de Snowflake&quot;,&quot;direccion&quot;:&quot;derecha&quot;,&quot;nodos&quot;:[{&quot;id&quot;:&quot;cta&quot;,&quot;label&quot;:&quot;Cuenta&quot;,&quot;icono&quot;:&quot;snowflake&quot;,&quot;col&quot;:1,&quot;fila&quot;:0,&quot;color&quot;:&quot;azul&quot;},{&quot;id&quot;:&quot;wh&quot;,&quot;label&quot;:&quot;Warehouses&quot;,&quot;icono&quot;:&quot;servidor&quot;,&quot;col&quot;:0,&quot;fila&quot;:1,&quot;color&quot;:&quot;naranja&quot;,&quot;sub&quot;:&quot;el cómputo&quot;},{&quot;id&quot;:&quot;ro&quot;,&quot;label&quot;:&quot;Roles y usuarios&quot;,&quot;icono&quot;:&quot;candado&quot;,&quot;col&quot;:1,&quot;fila&quot;:1,&quot;color&quot;:&quot;violeta&quot;,&quot;sub&quot;:&quot;la seguridad&quot;},{&quot;id&quot;:&quot;db&quot;,&quot;label&quot;:&quot;Bases de datos&quot;,&quot;icono&quot;:&quot;base&quot;,&quot;col&quot;:2,&quot;fila&quot;:1,&quot;color&quot;:&quot;verde&quot;},{&quot;id&quot;:&quot;es&quot;,&quot;label&quot;:&quot;Esquemas&quot;,&quot;icono&quot;:&quot;carpeta&quot;,&quot;col&quot;:2,&quot;fila&quot;:2,&quot;color&quot;:&quot;verde&quot;},{&quot;id&quot;:&quot;tv&quot;,&quot;label&quot;:&quot;Tablas y vistas&quot;,&quot;icono&quot;:&quot;tabla&quot;,&quot;col&quot;:1,&quot;fila&quot;:3,&quot;color&quot;:&quot;gris&quot;},{&quot;id&quot;:&quot;st&quot;,&quot;label&quot;:&quot;Stages&quot;,&quot;icono&quot;:&quot;archivos&quot;,&quot;col&quot;:3,&quot;fila&quot;:3,&quot;color&quot;:&quot;gris&quot;,&quot;sub&quot;:&quot;archivos para cargar&quot;}],&quot;grupos&quot;:[],&quot;flechas&quot;:[{&quot;de&quot;:&quot;cta&quot;,&quot;a&quot;:&quot;wh&quot;,&quot;label&quot;:&quot;&quot;,&quot;doble&quot;:false,&quot;sinpunta&quot;:false},{&quot;de&quot;:&quot;cta&quot;,&quot;a&quot;:&quot;ro&quot;,&quot;label&quot;:&quot;&quot;,&quot;doble&quot;:false,&quot;sinpunta&quot;:false},{&quot;de&quot;:&quot;cta&quot;,&quot;a&quot;:&quot;db&quot;,&quot;label&quot;:&quot;&quot;,&quot;doble&quot;:false,&quot;sinpunta&quot;:false},{&quot;de&quot;:&quot;db&quot;,&quot;a&quot;:&quot;es&quot;,&quot;label&quot;:&quot;&quot;,&quot;doble&quot;:false,&quot;sinpunta&quot;:false},{&quot;de&quot;:&quot;es&quot;,&quot;a&quot;:&quot;tv&quot;,&quot;label&quot;:&quot;&quot;,&quot;doble&quot;:false,&quot;sinpunta&quot;:false},{&quot;de&quot;:&quot;es&quot;,&quot;a&quot;:&quot;st&quot;,&quot;label&quot;:&quot;&quot;,&quot;doble&quot;:false,&quot;sinpunta&quot;:false}]}\"><figcaption>Los objetos de Snowflake</figcaption></figure>\n\n\n<p>El nombre completo de una tabla es <strong><code>BASE.ESQUEMA.TABLA</code></strong>, por ejemplo <code>TIENDA_ANDINA.PUBLIC.PEDIDOS</code>.</p>\n<h2>Paso 3 — Snowsight</h2>\n<p>Abre el <a href=\"#/snowflake\">Snowflake de práctica</a>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s01-home.webp\" alt=\"La navegación (1), la explicación de la práctica (2) y los accesos a una hoja SQL, los datos y los warehouses (3)\" loading=\"lazy\"><figcaption>La navegación (1), la explicación de la práctica (2) y los accesos a una hoja SQL, los datos y los warehouses (3)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Sección</th>\n<th>Qué tiene</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Projects</strong></td>\n<td>Worksheets (hojas SQL), Notebooks, Streamlit, Dashboards</td>\n</tr>\n<tr>\n<td><strong>Data</strong></td>\n<td>Databases (el explorador de objetos) y Marketplace</td>\n</tr>\n<tr>\n<td><strong>Monitoring</strong></td>\n<td>Query History, Copy History, Task History</td>\n</tr>\n<tr>\n<td><strong>Admin</strong></td>\n<td>Warehouses, Cost Management, Users &amp; Roles</td>\n</tr>\n</tbody></table></div>\n<p>El botón <strong>Create</strong> crea cualquier objeto:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s01-crear.webp\" alt=\"Create - SQL Worksheet, Database, Warehouse, Stage y Table\" loading=\"lazy\"><figcaption>Create - SQL Worksheet, Database, Warehouse, Stage y Table</figcaption></figure>\n\n\n<h2>Paso 4 — Qué es real en la práctica</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Real</th>\n<th>Simulado</th>\n</tr>\n</thead><tbody><tr>\n<td>El SQL corre de verdad (sobre DuckDB en tu navegador) con la sintaxis de Snowflake</td>\n<td>No hay cuenta ni nube: todo vive en tu navegador</td>\n</tr>\n<tr>\n<td>Warehouses que se encienden, suspenden y gastan créditos estimados</td>\n<td>Los créditos son una estimación, no una factura</td>\n</tr>\n<tr>\n<td>Stages, COPY INTO, JSON, MERGE, Time Travel, clones, roles y permisos</td>\n<td>Notebooks, Streamlit, Marketplace y Task History muestran qué son, sin simularlos</td>\n</tr>\n</tbody></table></div>\n<p>Los datos son los de <strong>Tienda Andina</strong>, la misma tienda del resto del curso: 12.000 pedidos, clientes, productos y detalle.</p>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Dejar un warehouse encendido &quot;por las dudas&quot;.</strong> Cobra por segundo mientras está prendido, aunque no corra nada; con AUTO_SUSPEND se apaga solo.</li>\n<li><strong>Confundir warehouse con base de datos.</strong> El warehouse es el motor que calcula; los datos viven en las bases, que existen aunque todos los warehouses estén apagados.</li>\n<li><strong>Escribir el nombre de la tabla sin contexto.</strong> Si la hoja no tiene base y esquema elegidos, usa el nombre completo <code>BASE.ESQUEMA.TABLA</code>.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Sabes qué es Snowflake y sus tres capas.</li>\n<li>Conoces la jerarquía de objetos.</li>\n<li>Ubicas cada sección de Snowsight.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-que-es-snowflake-y-snowsight-ej1","opciones":[{"text":"Una base de datos con sus esquemas y tablas","ok":false},{"text":"El cómputo que ejecuta las consultas, que se prende y apaga","ok":true},{"text":"El disco donde se guardan las tablas","ok":false},{"text":"Un usuario de servicio que ejecuta las cargas","ok":false}],"enunciado":"<p>¿Qué es un warehouse virtual en Snowflake?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-que-es-snowflake-y-snowsight-ej2","opciones":[{"text":"Porque el cómputo solo se paga mientras está encendido y se dimensiona por trabajo","ok":true},{"text":"Porque los datos no ocupan espacio","ok":false},{"text":"Porque los datos se borran al apagar el warehouse","ok":false},{"text":"Porque el almacenamiento se cobra solo cuando se consulta","ok":false}],"enunciado":"<p>¿Por qué separar almacenamiento y cómputo ahorra dinero?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-que-es-snowflake-y-snowsight-ej3","opciones":[{"text":"TABLA.BASE","ok":false},{"text":"BASE.ESQUEMA.TABLA","ok":true},{"text":"ESQUEMA.BASE.TABLA","ok":false},{"text":"WAREHOUSE.ESQUEMA.TABLA","ok":false}],"enunciado":"<p>¿Cuál es el nombre completo de una tabla?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-que-es-snowflake-y-snowsight-ej4","opciones":[{"text":"Projects","ok":false},{"text":"Data","ok":false},{"text":"Monitoring","ok":false},{"text":"Admin","ok":true}],"enunciado":"<p>¿En qué sección están Warehouses y Users &amp; Roles?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true}]},"snowflake-paso-a-paso-hojas-sql-y-contexto":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Las cuatro preguntas antes de cocinar</div>\n\n<p>Cada consulta responde cuatro preguntas antes de empezar: <strong>quién</strong> cocina (el rol, que decide qué puede tocar), <strong>con qué hornalla</strong> (el warehouse, que pone el cómputo), en <strong>qué despensa</strong> (la base) y en <strong>qué estante</strong> (el esquema). Si una falta o está mal, la receta falla aunque el SQL esté perfecto.</p>\n</div>\n\n\n<h2>Paso 1 — Una hoja nueva</h2>\n<p><strong>+ SQL Worksheet</strong> (o <strong>Create → SQL Worksheet</strong>). Ponle nombre y escribe:</p>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">-- Pedidos de la tienda por canal de venta\nSELECT canal, COUNT(*) AS pedidos\nFROM pedidos\nGROUP BY canal\nORDER BY pedidos DESC;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s02-hoja.webp\" alt=\"El nombre de la hoja (1), el rol y el warehouse (2), la base y el esquema (3), el botón de ejecutar (4) y el explorador de objetos (5)\" loading=\"lazy\"><figcaption>El nombre de la hoja (1), el rol y el warehouse (2), la base y el esquema (3), el botón de ejecutar (4) y el explorador de objetos (5)</figcaption></figure>\n\n\n<h2>Paso 2 — El contexto</h2>\n<p>Cada consulta corre con cuatro datos de contexto:</p>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Dato</th>\n<th>Qué decide</th>\n<th>Cómo se cambia</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Rol</strong></td>\n<td>Qué puedes ver y hacer</td>\n<td><code>USE ROLE sysadmin;</code> o el selector</td>\n</tr>\n<tr>\n<td><strong>Warehouse</strong></td>\n<td>Con qué cómputo corre (y quién paga)</td>\n<td><code>USE WAREHOUSE compute_wh;</code></td>\n</tr>\n<tr>\n<td><strong>Base</strong></td>\n<td>Dónde buscar las tablas sin nombre completo</td>\n<td><code>USE DATABASE tienda_andina;</code></td>\n</tr>\n<tr>\n<td><strong>Esquema</strong></td>\n<td>Ídem, dentro de la base</td>\n<td><code>USE SCHEMA tienda_andina.public;</code></td>\n</tr>\n</tbody></table></div>\n<p>Como el contexto es <code>TIENDA_ANDINA.PUBLIC</code>, <code>FROM pedidos</code> encuentra <code>TIENDA_ANDINA.PUBLIC.PEDIDOS</code>.</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s02-contexto.webp\" alt=\"El selector de rol y warehouse - roles del sistema y COMPUTE_WH (X-Small)\" loading=\"lazy\"><figcaption>El selector de rol y warehouse - roles del sistema y COMPUTE_WH (X-Small)</figcaption></figure>\n\n\n<h2>Paso 3 — Ejecutar</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Atajo</th>\n<th>Qué ejecuta</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Ctrl+Enter</strong> o ▶</td>\n<td>La sentencia donde está el cursor (o lo seleccionado)</td>\n</tr>\n<tr>\n<td><strong>Ctrl+Shift+Enter</strong> o Run all</td>\n<td>Todas las sentencias de la hoja, en orden</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 4 — El resultado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s02-resultado.webp\" alt=\"El resultado (1) - web, app, tienda y teléfono - y los Query Details (2) con el Query ID, la duración y las filas\" loading=\"lazy\"><figcaption>El resultado (1) - web, app, tienda y teléfono - y los Query Details (2) con el Query ID, la duración y las filas</figcaption></figure>\n\n\n<p>El <strong>Query ID</strong> identifica la consulta para siempre: sirve para buscarla en el historial, para Time Travel (nivel 4) y para pedir ayuda a soporte.</p>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 El warehouse se prende solo</div>\n\n<p>Si el warehouse estaba suspendido, la primera consulta lo enciende (<code>AUTO_RESUME</code>). Por eso la primera puede tardar un segundo más.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Ejecutar con el rol equivocado.</strong> Un &quot;does not exist or not authorized&quot; muchas veces es el rol de la hoja, no el nombre de la tabla.</li>\n<li><strong>No tener warehouse elegido.</strong> Sin warehouse, la consulta no puede correr: &quot;No active warehouse selected&quot;.</li>\n<li><strong>Ejecutar todo cuando querías una sentencia.</strong> Ctrl+Enter corre la sentencia del cursor; &quot;Run All&quot; corre la hoja entera, incluidos <code>DROP</code> o <code>DELETE</code> que dejaste más abajo.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Creaste una hoja y ejecutaste SQL.</li>\n<li>Entiendes el contexto de la sesión.</li>\n<li>Lees el resultado y el Query ID.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-hojas-sql-y-contexto-ej1","opciones":[{"text":"Rol, warehouse, base y esquema","ok":true},{"text":"Usuario, contraseña, IP y fecha","ok":false},{"text":"Tabla, columna, fila y valor","ok":false},{"text":"Cuenta, región, nube y edición","ok":false}],"enunciado":"<p>¿Qué cuatro datos forman el contexto de una consulta?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-hojas-sql-y-contexto-ej2","opciones":[{"text":"Ejecuta todas las sentencias","ok":false},{"text":"Ejecuta la sentencia donde está el cursor","ok":true},{"text":"Guarda la hoja","ok":false},{"text":"Formatea el SQL de la hoja","ok":false}],"enunciado":"<p>¿Qué hace Ctrl+Enter en una hoja?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-hojas-sql-y-contexto-ej3","opciones":[{"text":"Ninguna, falta el nombre completo","ok":false},{"text":"TIENDA_ANDINA.PUBLIC.PEDIDOS","ok":true},{"text":"Todas las tablas pedidos de la cuenta","ok":false},{"text":"La primera que encuentre","ok":false}],"enunciado":"<p>El contexto es TIENDA_ANDINA.PUBLIC. ¿Qué tabla lee <code>FROM pedidos</code>?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-hojas-sql-y-contexto-ej4","opciones":[{"text":"Para saber cuántos créditos tiene la cuenta","ok":false},{"text":"Para identificar la consulta en el historial, en Time Travel y con soporte","ok":true},{"text":"Para cambiar de rol","ok":false},{"text":"Para compartir la hoja con otro usuario","ok":false}],"enunciado":"<p>¿Para qué sirve el Query ID?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true}]},"snowflake-paso-a-paso-explorar-datos":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Leer las etiquetas antes de abrir las cajas</div>\n\n<p>Explorar la base desde Data es leer las etiquetas de las cajas del depósito: qué contiene cada una, de qué tipo y cuánto pesa. Recién después abres la caja que te interesa con una consulta.</p>\n</div>\n\n\n<h2>Paso 1 — Databases</h2>\n<p><strong>Data → Databases</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s03-databases.webp\" alt=\"El explorador (1) y la lista de bases (2) - SNOWFLAKE_SAMPLE_DATA y TIENDA_ANDINA\" loading=\"lazy\"><figcaption>El explorador (1) y la lista de bases (2) - SNOWFLAKE_SAMPLE_DATA y TIENDA_ANDINA</figcaption></figure>\n\n\n<p><code>SNOWFLAKE_SAMPLE_DATA</code> es la base de muestra que trae toda cuenta de Snowflake (datos TPC-H, por ejemplo). <code>TIENDA_ANDINA</code> es la base del curso.</p>\n<h2>Paso 2 — Una tabla</h2>\n<p>Abre <code>TIENDA_ANDINA → PUBLIC → PEDIDOS</code>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s03-columnas.webp\" alt=\"Las pestañas Columns y Data Preview (1) y las columnas con su tipo (2)\" loading=\"lazy\"><figcaption>Las pestañas Columns y Data Preview (1) y las columnas con su tipo (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Tipo de Snowflake</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><code>NUMBER(38,0)</code> / <code>NUMBER(10,2)</code></td>\n<td>Enteros y decimales (<code>INT</code> es un alias de <code>NUMBER(38,0)</code>)</td>\n</tr>\n<tr>\n<td><code>VARCHAR</code></td>\n<td>Texto (sin largo, ocupa solo lo que usa)</td>\n</tr>\n<tr>\n<td><code>DATE</code>, <code>TIMESTAMP_NTZ</code>, <code>TIMESTAMP_TZ</code></td>\n<td>Fechas y fechas con hora</td>\n</tr>\n<tr>\n<td><code>BOOLEAN</code></td>\n<td>Verdadero o falso</td>\n</tr>\n<tr>\n<td><code>VARIANT</code></td>\n<td>JSON y datos semiestructurados (nivel 3)</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 3 — Vista previa</h2>\n<p><strong>Data Preview</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s03-preview.webp\" alt=\"Las primeras filas de PEDIDOS\" loading=\"lazy\"><figcaption>Las primeras filas de PEDIDOS</figcaption></figure>\n\n\n<p><strong>Open in Worksheet</strong> abre una hoja con <code>SELECT * FROM ... LIMIT 100</code> y el contexto ya puesto.</p>\n<div class=\"callout callout-cuidado\"><div class=\"callout-title\">⚠️ La vista previa también usa el warehouse</div>\n\n<p>Ver datos ejecuta una consulta, así que enciende el warehouse y consume créditos. En tablas enormes, usa siempre <code>LIMIT</code>.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Creer que la vista previa es gratis.</strong> En Snowflake ejecuta una consulta con el warehouse, así que gasta créditos (poco, pero gasta).</li>\n<li><strong>Guardar JSON en VARCHAR.</strong> Pierdes la notación <code>:</code> y la conversión con <code>::</code>; el JSON va en VARIANT.</li>\n<li><strong>Ignorar mayúsculas en los nombres.</strong> Sin comillas, Snowflake guarda los nombres en mayúsculas; <code>&quot;pedidos&quot;</code> entre comillas es otro objeto que <code>pedidos</code>.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Navegas bases, esquemas y tablas.</li>\n<li>Lees columnas y tipos.</li>\n<li>Sabes ver datos sin escribir SQL.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-explorar-datos-ej1","opciones":[{"text":"Data → Databases → la tabla → Columns","ok":true},{"text":"En Query History","ok":false},{"text":"En Warehouses","ok":false},{"text":"En Marketplace","ok":false}],"enunciado":"<p>¿Dónde ves las columnas y tipos de una tabla sin escribir SQL?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-explorar-datos-ej2","opciones":[{"text":"VARCHAR(16)","ok":false},{"text":"NUMBER","ok":false},{"text":"VARIANT","ok":true},{"text":"BOOLEAN","ok":false}],"enunciado":"<p>¿Qué tipo usa Snowflake para JSON?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-explorar-datos-ej3","opciones":[{"text":"No, nunca","ok":false},{"text":"Sí, ejecuta una consulta con el warehouse","ok":true},{"text":"Solo si la tabla tiene más de un millón de filas","ok":false},{"text":"Solo si el warehouse es Medium o más grande","ok":false}],"enunciado":"<p>¿Ver la vista previa de una tabla gasta créditos?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-explorar-datos-ej4","opciones":[{"text":"Una base que hay que comprar","ok":false},{"text":"La base de datos de muestra que trae toda cuenta","ok":true},{"text":"Un warehouse","ok":false},{"text":"Un esquema que se crea dentro de cada base nueva","ok":false}],"enunciado":"<p>¿Qué es SNOWFLAKE_SAMPLE_DATA?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true}]},"snowflake-paso-a-paso-proyecto-ventas-por-pais":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El pedido</div>\n\n<p>Comercial: <em>&quot;Necesito cuántos pedidos entregados y cuánto vendimos en cada país, ordenado de mayor a menor.&quot;</em></p>\n</div>\n\n\n<h2>Paso 1 — La consulta</h2>\n<p>Hoja nueva, nombre <strong>Ventas por país</strong>:</p>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT c.pais,\n       COUNT(DISTINCT p.pedido_id) AS pedidos,\n       ROUND(SUM(d.cantidad * d.precio_unitario), 2) AS ventas\nFROM pedidos p\nJOIN clientes c ON c.cliente_id = p.cliente_id\nJOIN detalle_pedidos d ON d.pedido_id = p.pedido_id\nWHERE p.estado = 'entregado'\nGROUP BY c.pais\nORDER BY ventas DESC;</code></pre>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Parte</th>\n<th>Por qué</th>\n</tr>\n</thead><tbody><tr>\n<td><code>JOIN clientes</code></td>\n<td>El país está en el cliente, no en el pedido</td>\n</tr>\n<tr>\n<td><code>JOIN detalle_pedidos</code></td>\n<td>El importe está en cada línea del pedido</td>\n</tr>\n<tr>\n<td><code>COUNT(DISTINCT p.pedido_id)</code></td>\n<td>Un pedido tiene varias líneas: sin <code>DISTINCT</code> contarías líneas</td>\n</tr>\n<tr>\n<td><code>WHERE p.estado = &#39;entregado&#39;</code></td>\n<td>Solo lo que se concretó</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — El resultado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s04-ventas.webp\" alt=\"La consulta (1) y el resultado por país (2) - Argentina, México y España a la cabeza\" loading=\"lazy\"><figcaption>La consulta (1) y el resultado por país (2) - Argentina, México y España a la cabeza</figcaption></figure>\n\n\n<h2>Paso 3 — Un error a propósito</h2>\n<p>Escribe <code>FROM pedido</code> (sin la s):</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s04-error.webp\" alt=\"SQL compilation error - Object 'PEDIDO' does not exist or not authorized\" loading=\"lazy\"><figcaption>SQL compilation error - Object 'PEDIDO' does not exist or not authorized</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Parte del mensaje</th>\n<th>Qué dice</th>\n</tr>\n</thead><tbody><tr>\n<td><code>000904 (42000)</code></td>\n<td>Código del error</td>\n</tr>\n<tr>\n<td><code>SQL compilation error</code></td>\n<td>Falló al compilar: la consulta ni empezó a correr</td>\n</tr>\n<tr>\n<td><code>does not exist or not authorized</code></td>\n<td>O el nombre está mal, <strong>o</strong> tu rol no tiene permiso. Snowflake no dice cuál, por seguridad</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 Antes de pedir permiso</div>\n\n<p>Ante &quot;does not exist or not authorized&quot;, revisa primero el nombre y el contexto (base y esquema). Si están bien, es un tema de permisos (nivel 5).</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Contar pedidos con <code>COUNT(*)</code> después de unir con el detalle.</strong> Cada pedido aparece una vez por línea; se cuenta con <code>COUNT(DISTINCT pedido_id)</code>.</li>\n<li><strong>Leer &quot;does not exist or not authorized&quot; como &quot;no existe&quot;.</strong> Puede ser el nombre o el rol: revisa ambos.</li>\n<li><strong>Buscar el país en la tabla equivocada.</strong> En este modelo el país es del cliente; hace falta el JOIN con clientes.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lista de verificación</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  La hoja se llama &quot;Ventas por país&quot;.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  El resultado tiene una fila por país, ordenado por ventas.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Sabes por qué va <code>COUNT(DISTINCT ...)</code>.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Sabes leer el mensaje de error.</li>\n</ul>\n<h2>Lo que aprendiste en el nivel 1</h2>\n<ul>\n<li>Qué es Snowflake y Snowsight.</li>\n<li>Hojas SQL y el contexto.</li>\n<li>Explorar datos y leer errores.</li>\n</ul>\n<p>En el nivel 2: warehouses, bases, esquemas, tablas y el historial.</p>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-ventas-por-pais-ej1","opciones":[{"text":"Porque COUNT(*) ignora los pedidos cancelados","ok":false},{"text":"Porque al unir con el detalle cada pedido aparece una vez por línea","ok":true},{"text":"Para que sea más rápido","ok":false},{"text":"Porque así la consulta usa la caché","ok":false}],"enunciado":"<p>¿Por qué se usa COUNT(DISTINCT p.pedido_id)?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-ventas-por-pais-ej2","opciones":[{"text":"Que Snowflake está caído","ok":false},{"text":"Que el nombre está mal o el rol no tiene permiso","ok":true},{"text":"Que la tabla está vacía","ok":false},{"text":"Que falta un warehouse","ok":false}],"enunciado":"<p>¿Qué significa &quot;does not exist or not authorized&quot;?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-ventas-por-pais-ej3","opciones":[{"text":"Que la consulta falló antes de empezar a ejecutarse","ok":true},{"text":"Que corrió a medias","ok":false},{"text":"Que se borró la tabla","ok":false},{"text":"Que gastó muchos créditos","ok":false}],"enunciado":"<p>¿Qué indica &quot;SQL compilation error&quot;?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-ventas-por-pais-ej4","opciones":[{"text":"En pedidos","ok":false},{"text":"En clientes","ok":true},{"text":"En detalle_pedidos","ok":false},{"text":"En productos","ok":false}],"enunciado":"<p>¿Dónde está el país del pedido en este modelo?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true}]},"snowflake-paso-a-paso-warehouses":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El pedido</div>\n\n<p>Lucía, líder de datos: <em>&quot;Los analistas y la carga nocturna usan el mismo warehouse y se pisan. Quiero uno aparte para análisis, chico y que se apague solo.&quot;</em></p>\n</div>\n\n\n<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Una cuadrilla que se contrata por segundo</div>\n\n<p>Un warehouse es una cuadrilla de trabajadores: un X-Small es una cuadrilla chica y cada talla duplica la gente y el costo por hora. Agrandarla (scale up) termina antes un trabajo pesado; agregar cuadrillas iguales (scale out) atiende a más clientes a la vez. Y la cuadrilla se paga solo mientras está trabajando.</p>\n</div>\n\n\n<h2>Paso 1 — Crear el warehouse</h2>\n<p><strong>Admin → Warehouses → + Warehouse</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s05-nuevo.webp\" alt=\"New Warehouse - nombre ANALISIS_WH, tamaño X-Small (1 crédito/hora), Auto suspend 1 minuto y el SQL equivalente\" loading=\"lazy\"><figcaption>New Warehouse - nombre ANALISIS_WH, tamaño X-Small (1 crédito/hora), Auto suspend 1 minuto y el SQL equivalente</figcaption></figure>\n\n\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE WAREHOUSE analisis_wh\n  WAREHOUSE_SIZE = 'XSMALL'\n  AUTO_SUSPEND = 60\n  AUTO_RESUME = TRUE\n  INITIALLY_SUSPENDED = TRUE;</code></pre>\n<h2>Paso 2 — Cómo se cobra</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s05-lista.webp\" alt=\"Los créditos consumidos y su equivalente en dólares (1) y los warehouses con estado, tamaño, créditos por hora y auto suspend (2)\" loading=\"lazy\"><figcaption>Los créditos consumidos y su equivalente en dólares (1) y los warehouses con estado, tamaño, créditos por hora y auto suspend (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Tamaño</th>\n<th>Créditos por hora</th>\n</tr>\n</thead><tbody><tr>\n<td>X-Small</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Small</td>\n<td>2</td>\n</tr>\n<tr>\n<td>Medium</td>\n<td>4</td>\n</tr>\n<tr>\n<td>Large</td>\n<td>8</td>\n</tr>\n<tr>\n<td>X-Large</td>\n<td>16</td>\n</tr>\n</tbody></table></div>\n<ul>\n<li>Se cobra <strong>por segundo</strong> mientras está encendido, con un <strong>mínimo de 60 segundos</strong> cada vez que arranca.</li>\n<li>Suspendido <strong>no cobra</strong>.</li>\n<li>El precio del crédito depende de la edición y la región (en la práctica se estima en USD 3).</li>\n</ul>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Opción</th>\n<th>Qué hace</th>\n</tr>\n</thead><tbody><tr>\n<td><code>AUTO_SUSPEND = 60</code></td>\n<td>Se apaga tras 60 segundos sin consultas</td>\n</tr>\n<tr>\n<td><code>AUTO_RESUME = TRUE</code></td>\n<td>La próxima consulta lo prende sola</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 3 — Cambiar el tamaño</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE WAREHOUSE analisis_wh;\nALTER WAREHOUSE analisis_wh SET WAREHOUSE_SIZE = 'SMALL';\nSHOW WAREHOUSES;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s05-alter.webp\" alt=\"La hoja usa ANALISIS_WH (1) y SHOW WAREHOUSES lo muestra en Small (2)\" loading=\"lazy\"><figcaption>La hoja usa ANALISIS_WH (1) y SHOW WAREHOUSES lo muestra en Small (2)</figcaption></figure>\n\n\n<h2>Paso 4 — ¿Más grande o más clústeres?</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Problema</th>\n<th>Solución</th>\n<th>Cómo</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Una</strong> consulta pesada tarda mucho</td>\n<td><strong>Scale up</strong>: un tamaño más</td>\n<td><code>WAREHOUSE_SIZE = &#39;MEDIUM&#39;</code></td>\n</tr>\n<tr>\n<td><strong>Muchas</strong> consultas chicas hacen cola</td>\n<td><strong>Scale out</strong>: más clústeres del mismo tamaño</td>\n<td><code>MIN_CLUSTER_COUNT = 1 MAX_CLUSTER_COUNT = 3</code> (edición Enterprise)</td>\n</tr>\n</tbody></table></div>\n<p>Duplicar el tamaño duplica el costo por hora, pero si la consulta tarda la mitad, el costo total es el mismo y el resultado llega antes.</p>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Agrandar para atender a más usuarios.</strong> Si el problema es que muchas consultas esperan en cola, conviene multi-clúster (scale out), no una talla mayor.</li>\n<li><strong>AUTO_SUSPEND muy largo o en 0.</strong> Un warehouse que nunca se apaga cobra toda la noche; para análisis, 60 a 300 segundos alcanza.</li>\n<li><strong>Un solo warehouse para todo.</strong> Cargas y análisis se pisan y no sabes quién gasta; usa uno por carga de trabajo.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Creaste un warehouse con auto suspend.</li>\n<li>Entiendes tamaños y créditos.</li>\n<li>Sabes cuándo agrandar y cuándo agregar clústeres.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-warehouses-ej1","opciones":[{"text":"1","ok":false},{"text":"2","ok":true},{"text":"4","ok":false},{"text":"8","ok":false}],"enunciado":"<p>¿Cuántos créditos por hora gasta un warehouse Small?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-warehouses-ej2","opciones":[{"text":"Apaga el warehouse después de 60 segundos sin consultas","ok":true},{"text":"Lo prende cada 60 segundos","ok":false},{"text":"Limita las consultas a 60","ok":false},{"text":"Suspende las consultas que tardan más de 60 segundos","ok":false}],"enunciado":"<p>¿Qué hace AUTO_SUSPEND = 60?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-warehouses-ej3","opciones":[{"text":"Subir el tamaño (scale up)","ok":true},{"text":"Agregar clústeres (scale out)","ok":false},{"text":"Bajar AUTO_SUSPEND a 30 segundos","ok":false},{"text":"Cambiar al rol ACCOUNTADMIN, que tiene más prioridad","ok":false}],"enunciado":"<p>Una consulta pesada tarda 20 minutos en X-Small. ¿Qué pruebas primero?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-warehouses-ej4","opciones":[{"text":"Un warehouse 4X-Large","ok":false},{"text":"Un warehouse multi-clúster (scale out)","ok":true},{"text":"AUTO_SUSPEND = 0","ok":false},{"text":"Un esquema nuevo","ok":false}],"enunciado":"<p>50 analistas lanzan consultas chicas a la vez y hacen cola. ¿Qué conviene?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true}]},"snowflake-paso-a-paso-bases-esquemas-y-tablas":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Edificio, pisos y cajones</div>\n\n<p>Una base es un edificio, cada esquema es un piso con su propia llave y cada tabla es un cajón. Separar raw y analitica en pisos distintos permite dar la llave de un piso sin abrir el otro.</p>\n</div>\n\n\n<h2>Paso 1 — El entorno</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE DATABASE tienda_dev;\nCREATE SCHEMA tienda_dev.raw;\nCREATE SCHEMA tienda_dev.analitica;\nUSE SCHEMA tienda_dev.analitica;\n\nCREATE TABLE ventas_por_canal AS\nSELECT canal, COUNT(*) AS pedidos\nFROM tienda_andina.public.pedidos\nGROUP BY canal;\n\nSELECT * FROM ventas_por_canal ORDER BY pedidos DESC;</code></pre>\n<p>Ejecuta todo con <strong>Run all</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s06-crear.webp\" alt=\"TIENDA_DEV con sus esquemas en el explorador (1), el contexto ya en TIENDA_DEV.ANALITICA (2) y las 6 sentencias ejecutadas (3)\" loading=\"lazy\"><figcaption>TIENDA_DEV con sus esquemas en el explorador (1), el contexto ya en TIENDA_DEV.ANALITICA (2) y las 6 sentencias ejecutadas (3)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Sentencia</th>\n<th>Qué hace</th>\n</tr>\n</thead><tbody><tr>\n<td><code>CREATE DATABASE</code></td>\n<td>Crea la base (y su esquema <code>PUBLIC</code>)</td>\n</tr>\n<tr>\n<td><code>CREATE SCHEMA base.esquema</code></td>\n<td>Crea un esquema dentro de la base</td>\n</tr>\n<tr>\n<td><code>USE SCHEMA</code></td>\n<td>Cambia el contexto</td>\n</tr>\n<tr>\n<td><code>CREATE TABLE ... AS SELECT</code> (CTAS)</td>\n<td>Crea la tabla con las columnas y filas del SELECT</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — En el explorador</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s06-tabla.webp\" alt=\"TIENDA_DEV / ANALITICA / VENTAS_POR_CANAL (1) y sus columnas CANAL y PEDIDOS (2)\" loading=\"lazy\"><figcaption>TIENDA_DEV / ANALITICA / VENTAS_POR_CANAL (1) y sus columnas CANAL y PEDIDOS (2)</figcaption></figure>\n\n\n<h2>Paso 3 — Esquemas por capa</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Esquema</th>\n<th>Qué guarda</th>\n<th>Quién escribe</th>\n</tr>\n</thead><tbody><tr>\n<td><code>raw</code></td>\n<td>Los datos tal como llegan</td>\n<td>Las cargas</td>\n</tr>\n<tr>\n<td><code>analitica</code></td>\n<td>Tablas limpias y agregadas para el negocio</td>\n<td>Las transformaciones</td>\n</tr>\n</tbody></table></div>\n<p>Separar por esquema permite dar permisos distintos (los analistas leen <code>analitica</code>, no <code>raw</code>) y saber qué está listo para usar.</p>\n<h2>Paso 4 — Tipos de tabla</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Tipo</th>\n<th>Time Travel</th>\n<th>Fail-safe</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Permanente</strong> (por defecto)</td>\n<td>1 día (hasta 90 en Enterprise)</td>\n<td>7 días</td>\n<td>Datos que importan</td>\n</tr>\n<tr>\n<td><strong>Transitoria</strong> (<code>CREATE TRANSIENT TABLE</code>)</td>\n<td>0 o 1 día</td>\n<td>No</td>\n<td>Datos que se pueden volver a cargar: staging, intermedias</td>\n</tr>\n<tr>\n<td><strong>Temporal</strong> (<code>CREATE TEMPORARY TABLE</code>)</td>\n<td>0 o 1 día</td>\n<td>No</td>\n<td>Solo existe en tu sesión</td>\n</tr>\n</tbody></table></div>\n<p><strong>Fail-safe</strong> es una copia de recuperación que solo Snowflake puede restaurar; ocupa almacenamiento y por eso cuesta.</p>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Staging en tablas permanentes.</strong> Una tabla que se recarga cada día no necesita Fail-safe; transitoria cuesta menos.</li>\n<li><strong>Trabajar todo en PUBLIC.</strong> Mezcla capas y complica los permisos; crea esquemas por capa.</li>\n<li><strong>Nombres sin convención.</strong> <code>ventas</code>, <code>Ventas2</code> y <code>ventas_final_v3</code> en el mismo esquema confunden a todo el equipo.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Creaste una base con esquemas por capa.</li>\n<li>Creaste una tabla con CTAS.</li>\n<li>Conoces los tipos de tabla.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-bases-esquemas-y-tablas-ej1","opciones":[{"text":"Crea una vista","ok":false},{"text":"Crea una tabla con las columnas y filas que devuelve el SELECT","ok":true},{"text":"Crea una tabla vacía con el nombre ventas","ok":false},{"text":"Crea un esquema","ok":false}],"enunciado":"<p>¿Qué hace CREATE TABLE ventas AS SELECT ...?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-bases-esquemas-y-tablas-ej2","opciones":[{"text":"Para ordenar por capa y dar permisos distintos a cada una","ok":true},{"text":"Porque Snowflake lo exige","ok":false},{"text":"Para gastar menos créditos siempre","ok":false},{"text":"Porque cada esquema tiene su propio warehouse","ok":false}],"enunciado":"<p>¿Para qué separar los esquemas raw y analitica?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-bases-esquemas-y-tablas-ej3","opciones":[{"text":"Permanente con 90 días de Time Travel","ok":false},{"text":"Transitoria","ok":true},{"text":"Una tabla externa sobre el stage","ok":false},{"text":"Una vista","ok":false}],"enunciado":"<p>¿Qué tabla conviene para un staging que se recarga cada día?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-bases-esquemas-y-tablas-ej4","opciones":[{"text":"RAW","ok":false},{"text":"PUBLIC","ok":true},{"text":"MAIN","ok":false},{"text":"DEFAULT","ok":false}],"enunciado":"<p>¿Qué esquema crea Snowflake al crear una base?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true}]},"snowflake-paso-a-paso-historial-de-consultas":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 La caja negra del avión</div>\n\n<p>El historial de consultas es la caja negra: registra cada sentencia con quién la ejecutó, con qué rol y warehouse, cuánto tardó y si falló. Cuando algo sale mal, primero se lee la caja negra.</p>\n</div>\n\n\n<h2>Paso 1 — El historial</h2>\n<p><strong>Monitoring → Query History</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s07-historial.webp\" alt=\"Los filtros All, Succeeded y Failed (1) y cada sentencia con su estado, SQL, Query ID, warehouse, rol, duración y filas (2)\" loading=\"lazy\"><figcaption>Los filtros All, Succeeded y Failed (1) y cada sentencia con su estado, SQL, Query ID, warehouse, rol, duración y filas (2)</figcaption></figure>\n\n\n<h2>Paso 2 — Las fallidas</h2>\n<p><strong>Failed</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s07-fallidas.webp\" alt=\"La consulta fallida del proyecto 1 - FROM pedido\" loading=\"lazy\"><figcaption>La consulta fallida del proyecto 1 - FROM pedido</figcaption></figure>\n\n\n<p>Haz clic en la fila:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s07-detalle.webp\" alt=\"El detalle - estado, rol, warehouse, contexto, duración, el SQL y el error, con Open in Worksheet\" loading=\"lazy\"><figcaption>El detalle - estado, rol, warehouse, contexto, duración, el SQL y el error, con Open in Worksheet</figcaption></figure>\n\n\n<h2>Paso 3 — Para qué sirve</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Pregunta</th>\n<th>Qué mirar</th>\n</tr>\n</thead><tbody><tr>\n<td>¿Por qué falló el reporte de esta mañana?</td>\n<td>Failed, el error y el rol con el que corrió</td>\n</tr>\n<tr>\n<td>¿Qué consulta tarda tanto?</td>\n<td>Ordenar por <strong>Duration</strong></td>\n</tr>\n<tr>\n<td>¿Quién gasta el warehouse?</td>\n<td>El rol y el warehouse de las consultas más largas</td>\n</tr>\n<tr>\n<td>¿Qué SQL ejecutó la carga?</td>\n<td>El texto completo, que se puede reabrir</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-nota\"><div class=\"callout-title\">📝 En Snowflake real, con SQL</div>\n\n<p>El historial también se consulta con SQL: <code>SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY</code> guarda un año de historia (con hasta 45 minutos de demora) y la función <code>INFORMATION_SCHEMA.QUERY_HISTORY()</code> los últimos 7 días al instante. El <strong>Query Profile</strong> de cada consulta muestra paso a paso dónde se fue el tiempo.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Buscar solo en la hoja.</strong> Si la consulta la corrió otra persona o un proceso, está en Query History (o en ACCOUNT_USAGE), no en tu hoja.</li>\n<li><strong>Mirar solo la duración.</strong> Una consulta lenta puede estar esperando en cola por un warehouse saturado; el Query Profile muestra dónde se fue el tiempo.</li>\n<li><strong>Olvidar el retraso de ACCOUNT_USAGE.</strong> Sus vistas tienen hasta unas horas de demora; para lo de hace minutos usa Query History o INFORMATION_SCHEMA.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Lees y filtras el historial.</li>\n<li>Abres el detalle de una consulta.</li>\n<li>Sabes usarlo para diagnosticar.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-historial-de-consultas-ej1","opciones":[{"text":"Query History con el filtro Failed","ok":true},{"text":"Warehouses","ok":false},{"text":"Marketplace","ok":false},{"text":"Users &amp; Roles","ok":false}],"enunciado":"<p>¿Dónde encuentras la consulta que falló esta mañana?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-historial-de-consultas-ej2","opciones":[{"text":"Rows","ok":false},{"text":"Duration","ok":true},{"text":"Role","ok":false},{"text":"Status","ok":false}],"enunciado":"<p>¿Qué columna ordenas para encontrar la consulta más lenta?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-historial-de-consultas-ej3","opciones":[{"text":"INFORMATION_SCHEMA.TABLES","ok":false},{"text":"SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY","ok":true},{"text":"PUBLIC.HISTORIAL","ok":false},{"text":"INFORMATION_SCHEMA.QUERY_HISTORY","ok":false}],"enunciado":"<p>¿Qué vista de Snowflake guarda un año de historial de consultas?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-historial-de-consultas-ej4","opciones":[{"text":"El texto SQL de la consulta, formateado","ok":false},{"text":"Paso a paso dónde se fue el tiempo de una consulta","ok":true},{"text":"Los créditos de la cuenta","ok":false},{"text":"Los roles","ok":false}],"enunciado":"<p>¿Qué muestra el Query Profile?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true}]},"snowflake-paso-a-paso-proyecto-entorno-de-desarrollo":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El pedido</div>\n\n<p>Lucía: <em>&quot;Quiero <code>tienda_dev</code> con <code>raw</code> y <code>analitica</code>, un warehouse X-Small para análisis que se apague al minuto, y la tabla <code>ventas_por_canal</code> como primera prueba. Mostrame que está todo con SHOW.&quot;</em></p>\n</div>\n\n\n<h2>Lo que tienes que lograr</h2>\n<ol>\n<li>Base <code>tienda_dev</code> con esquemas <code>raw</code> y <code>analitica</code>.</li>\n<li>Warehouse <code>analisis_wh</code>, X-Small, <code>AUTO_SUSPEND = 60</code>, <code>AUTO_RESUME = TRUE</code>.</li>\n<li>Tabla <code>tienda_dev.analitica.ventas_por_canal</code>.</li>\n<li>Comprobarlo con <code>SHOW</code>.</li>\n</ol>\n<details><summary>💡 Pista: comprobar</summary>\n\n<p><code>SHOW WAREHOUSES;</code> lista los warehouses con su tamaño y auto suspend. <code>SHOW SCHEMAS IN DATABASE tienda_dev;</code> lista los esquemas.</p>\n</details>\n\n<h2>Cómo se ve terminado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s08-esquemas.webp\" alt=\"SHOW SCHEMAS IN DATABASE tienda_dev - ANALITICA, PUBLIC y RAW\" loading=\"lazy\"><figcaption>SHOW SCHEMAS IN DATABASE tienda_dev - ANALITICA, PUBLIC y RAW</figcaption></figure>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s08-warehouses.webp\" alt=\"SHOW WAREHOUSES - COMPUTE_WH y ANALISIS_WH en X-Small con auto_suspend 60\" loading=\"lazy\"><figcaption>SHOW WAREHOUSES - COMPUTE_WH y ANALISIS_WH en X-Small con auto_suspend 60</figcaption></figure>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Crear objetos a mano sin script.</strong> Nadie puede repetirlo igual en otra cuenta o entorno.</li>\n<li><strong>Olvidar <code>IF NOT EXISTS</code> o <code>OR REPLACE</code>.</strong> La segunda corrida del script falla, o peor, reemplaza algo que no querías.</li>\n<li><strong>Warehouse de desarrollo sin AUTO_SUSPEND.</strong> Es el que más se olvida encendido.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lista de verificación</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  <code>SHOW SCHEMAS IN DATABASE tienda_dev</code> devuelve ANALITICA, PUBLIC y RAW.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  <code>SHOW WAREHOUSES</code> muestra ANALISIS_WH en X-Small con auto_suspend 60.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  <code>SELECT * FROM tienda_dev.analitica.ventas_por_canal</code> devuelve 4 canales.</li>\n</ul>\n<details><summary>💡 Solución comentada</summary>\n\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE WAREHOUSE IF NOT EXISTS analisis_wh\n  WAREHOUSE_SIZE = 'XSMALL' AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE;\nCREATE DATABASE IF NOT EXISTS tienda_dev;\nCREATE SCHEMA IF NOT EXISTS tienda_dev.raw;\nCREATE SCHEMA IF NOT EXISTS tienda_dev.analitica;\nUSE WAREHOUSE analisis_wh;\nCREATE OR REPLACE TABLE tienda_dev.analitica.ventas_por_canal AS\nSELECT canal, COUNT(*) AS pedidos FROM tienda_andina.public.pedidos GROUP BY canal;\nSHOW SCHEMAS IN DATABASE tienda_dev;\nSHOW WAREHOUSES;</code></pre>\n<p><code>IF NOT EXISTS</code> y <code>CREATE OR REPLACE</code> hacen que el script se pueda correr dos veces sin error: es la base para automatizar el entorno (con Terraform o con el Snowflake CLI, nivel 6).</p>\n</details>\n\n<h2>Lo que aprendiste en el nivel 2</h2>\n<ul>\n<li>Warehouses, tamaños y créditos.</li>\n<li>Bases, esquemas y tipos de tabla.</li>\n<li>Query History.</li>\n</ul>\n<p>En el nivel 3: cargar archivos con stages y COPY INTO, JSON y MERGE.</p>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-entorno-de-desarrollo-ej1","opciones":[{"text":"Para que el script no falle si el objeto ya existe","ok":true},{"text":"Para borrar el objeto","ok":false},{"text":"Para que sea más rápido","ok":false},{"text":"Para que el objeto se borre si está vacío","ok":false}],"enunciado":"<p>¿Para qué sirve IF NOT EXISTS en un CREATE?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-entorno-de-desarrollo-ej2","opciones":[{"text":"LIST SCHEMAS","ok":false},{"text":"SHOW SCHEMAS IN DATABASE tienda_dev","ok":true},{"text":"SELECT * FROM schemas","ok":false},{"text":"DESCRIBE tienda_dev","ok":false}],"enunciado":"<p>¿Qué comando lista los esquemas de una base?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-entorno-de-desarrollo-ej3","opciones":[{"text":"Porque cuesta menos siempre","ok":false},{"text":"Para que no se pisen y para saber qué gasta cada uno","ok":true},{"text":"Porque Snowflake solo permite una consulta por warehouse","ok":false},{"text":"Para que la carga use la caché del análisis","ok":false}],"enunciado":"<p>¿Por qué un warehouse para análisis separado de la carga?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-entorno-de-desarrollo-ej4","opciones":[{"text":"Falla si existe","ok":false},{"text":"Reemplaza la tabla si ya existe","ok":true},{"text":"Agrega filas","ok":false},{"text":"Crea una vista","ok":false}],"enunciado":"<p>¿Qué hace CREATE OR REPLACE TABLE?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true}]},"snowflake-paso-a-paso-stages-y-copy-into":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El pedido</div>\n\n<p>Lucía: <em>&quot;El sistema de la tienda deja cada día un CSV con los pedidos. Quiero cargarlo a <code>raw.pedidos_staging</code>.&quot;</em></p>\n</div>\n\n\n<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 La sala de espera de los archivos</div>\n\n<p>Un stage es la sala de espera donde dejas los archivos antes de cargarlos. <code>COPY INTO</code> es el empleado que los hace pasar a la tabla, de a uno, revisando que vengan en el formato acordado (el file format).</p>\n</div>\n\n\n<h2>Paso 1 — Crear el stage</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE SCHEMA tienda_dev.raw;\nCREATE STAGE carga_pedidos;</code></pre>\n<p>Un <strong>stage</strong> es una carpeta donde se dejan archivos antes de cargarlos. Este es <strong>interno</strong>: los archivos viven dentro de Snowflake.</p>\n<h2>Paso 2 — Subir el archivo</h2>\n<p>En el explorador, abre <code>@CARGA_PEDIDOS</code> → <strong>+ Files</strong> y sube <code>pedidos_2026_11_14.csv</code>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s09-stage.webp\" alt=\"El stage con + Files (1) y el archivo subido (2)\" loading=\"lazy\"><figcaption>El stage con + Files (1) y el archivo subido (2)</figcaption></figure>\n\n\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">LIST @carga_pedidos;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s09-list.webp\" alt=\"LIST - nombre, tamaño, md5 y última modificación de cada archivo\" loading=\"lazy\"><figcaption>LIST - nombre, tamaño, md5 y última modificación de cada archivo</figcaption></figure>\n\n\n<div class=\"callout callout-nota\"><div class=\"callout-title\">📝 Fuera de Snowsight</div>\n\n<p>Desde la terminal se sube con el comando <code>PUT file:///datos/pedidos_2026_11_14.csv @carga_pedidos;</code> del Snowflake CLI o SnowSQL.</p>\n</div>\n\n\n<h2>Paso 3 — La primera carga (con error)</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE TABLE pedidos_staging (\n  pedido_id INT, cliente_id INT, fecha DATE, canal VARCHAR, total NUMBER(10,2)\n);\nCOPY INTO pedidos_staging FROM @carga_pedidos;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s09-error.webp\" alt=\"CSV Error on Line 1 - la primera línea es el encabezado y &quot;pedido_id&quot; no es un número\" loading=\"lazy\"><figcaption>CSV Error on Line 1 - la primera línea es el encabezado y &quot;pedido_id&quot; no es un número</figcaption></figure>\n\n\n<p>Por defecto COPY INTO <strong>aborta</strong> la carga ante el primer error (<code>ON_ERROR = ABORT_STATEMENT</code>): no carga nada a medias.</p>\n<h2>Paso 4 — Cargar bien</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">COPY INTO pedidos_staging\nFROM @carga_pedidos\nFILE_FORMAT = (TYPE = CSV SKIP_HEADER = 1);</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s09-copy.webp\" alt=\"El COPY INTO con el formato (1) y el resultado - archivo LOADED con 5 filas leídas y 5 cargadas (2)\" loading=\"lazy\"><figcaption>El COPY INTO con el formato (1) y el resultado - archivo LOADED con 5 filas leídas y 5 cargadas (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Opción</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><code>FILE_FORMAT = (TYPE = CSV SKIP_HEADER = 1)</code></td>\n<td>Saltear el encabezado</td>\n</tr>\n<tr>\n<td><code>FIELD_DELIMITER = &#39;;&#39;</code></td>\n<td>Archivos separados por punto y coma</td>\n</tr>\n<tr>\n<td><code>PATTERN = &#39;.*pedidos_.*[.]csv&#39;</code></td>\n<td>Cargar solo los archivos que coinciden</td>\n</tr>\n<tr>\n<td><code>ON_ERROR = CONTINUE</code></td>\n<td>Cargar las filas buenas y saltear las malas</td>\n</tr>\n<tr>\n<td><code>CREATE FILE FORMAT csv_tienda ...</code></td>\n<td>Guardar el formato con nombre y reusarlo</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 5 — Stages externos</h2>\n<p>En producción, los archivos suelen estar en S3, Azure Blob Storage o Google Cloud Storage. Se crea un <strong>stage externo</strong> que apunta al bucket mediante una <strong>storage integration</strong> (la credencial la administra Snowflake, no va en el SQL):</p>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE STAGE ventas_s3\n  URL = 's3://tienda-andina-landing/pedidos/'\n  STORAGE_INTEGRATION = s3_tienda\n  FILE_FORMAT = (TYPE = CSV SKIP_HEADER = 1);</code></pre>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>No declarar el encabezado.</strong> Sin <code>SKIP_HEADER = 1</code>, la primera fila (los nombres de columna) se intenta cargar como datos y falla.</li>\n<li><strong>Poner claves de la nube en el SQL.</strong> Para S3, Azure o GCS se usa una storage integration, no credenciales en la sentencia.</li>\n<li><strong>Usar <code>ON_ERROR = CONTINUE</code> sin revisar.</strong> Carga lo que puede y descarta filas en silencio; revisa el resultado o usa <code>VALIDATION_MODE</code> antes.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Creaste un stage, subiste y listaste archivos.</li>\n<li>Cargaste con COPY INTO y entendiste el error.</li>\n<li>Conoces las opciones y los stages externos.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-stages-y-copy-into-ej1","opciones":[{"text":"Un warehouse","ok":false},{"text":"Una ubicación donde se dejan archivos antes de cargarlos","ok":true},{"text":"Un warehouse dedicado a cargar archivos","ok":false},{"text":"Una tabla temporal con los datos ya cargados","ok":false}],"enunciado":"<p>¿Qué es un stage en Snowflake?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-stages-y-copy-into-ej2","opciones":[{"text":"Porque faltaba el warehouse","ok":false},{"text":"Porque el archivo tiene encabezado y la primera fila no es un número","ok":true},{"text":"Porque el stage estaba vacío","ok":false},{"text":"Porque el rol no tenía permisos","ok":false}],"enunciado":"<p>¿Por qué falló la primera carga?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-stages-y-copy-into-ej3","opciones":[{"text":"Aborta la carga entera","ok":true},{"text":"Carga todo menos la fila mala","ok":false},{"text":"Borra el archivo","ok":false},{"text":"Carga el archivo en una tabla de errores","ok":false}],"enunciado":"<p>¿Qué hace COPY INTO por defecto ante un error?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-stages-y-copy-into-ej4","opciones":[{"text":"Con un rol de ACCOUNTADMIN en el stage","ok":false},{"text":"Con una storage integration","ok":true},{"text":"Con el usuario y contraseña en la URL","ok":false},{"text":"Con las claves en un file format","ok":false}],"enunciado":"<p>¿Cómo accede un stage externo a un bucket de S3 sin poner claves en el SQL?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true}]},"snowflake-paso-a-paso-json-y-variant":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Una caja que acepta cualquier forma</div>\n\n<p>Una columna VARIANT es una caja que acepta objetos de cualquier forma: cada evento puede traer campos distintos. Con <code>:</code> buscas adentro de la caja, con <code>::</code> le pones una etiqueta de tipo al resultado y con <code>FLATTEN</code> vacías una lista en filas.</p>\n</div>\n\n\n<h2>Paso 1 — Guardar JSON</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE TABLE eventos_web (datos VARIANT);\n\nINSERT INTO eventos_web\nSELECT PARSE_JSON('{&quot;evento&quot;:&quot;compra&quot;,&quot;cliente&quot;:{&quot;id&quot;:5,&quot;pais&quot;:&quot;PE&quot;},&quot;items&quot;:[{&quot;sku&quot;:&quot;A1&quot;,&quot;cant&quot;:2},{&quot;sku&quot;:&quot;B7&quot;,&quot;cant&quot;:1}]}')\nUNION ALL SELECT PARSE_JSON('{&quot;evento&quot;:&quot;compra&quot;,&quot;cliente&quot;:{&quot;id&quot;:8,&quot;pais&quot;:&quot;CO&quot;},&quot;items&quot;:[{&quot;sku&quot;:&quot;C3&quot;,&quot;cant&quot;:4}]}')\nUNION ALL SELECT PARSE_JSON('{&quot;evento&quot;:&quot;visita&quot;,&quot;cliente&quot;:{&quot;id&quot;:12,&quot;pais&quot;:&quot;MX&quot;},&quot;items&quot;:[]}');</code></pre>\n<p>Una columna <strong>VARIANT</strong> guarda cualquier JSON (hasta 16 MB por valor) sin definir el esquema antes. Si mañana el evento trae un campo nuevo, no hay que cambiar la tabla.</p>\n<h2>Paso 2 — Leer campos</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT datos:evento::string       AS evento,\n       datos:cliente.id::int       AS cliente_id,\n       datos:cliente.pais::string  AS pais\nFROM eventos_web;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s10-rutas.webp\" alt=\"La consulta con la notación de dos puntos (1) y una fila por evento con su tipo, cliente y país (2)\" loading=\"lazy\"><figcaption>La consulta con la notación de dos puntos (1) y una fila por evento con su tipo, cliente y país (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Sintaxis</th>\n<th>Qué hace</th>\n</tr>\n</thead><tbody><tr>\n<td><code>datos:evento</code></td>\n<td>El campo <code>evento</code> del JSON</td>\n</tr>\n<tr>\n<td><code>datos:cliente.pais</code></td>\n<td>Un campo anidado</td>\n</tr>\n<tr>\n<td><code>datos:items[0]</code></td>\n<td>El primer elemento de un arreglo</td>\n</tr>\n<tr>\n<td><code>::string</code>, <code>::int</code>, <code>::date</code></td>\n<td>Convierte el valor al tipo (sin <code>::</code> queda como VARIANT, con comillas)</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 3 — Abrir los arreglos</h2>\n<p>Cada compra trae una lista de ítems. Para tener una fila por ítem:</p>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT e.datos:cliente.pais::string AS pais,\n       f.value:sku::string          AS sku,\n       f.value:cant::int            AS cantidad,\n       f.index                      AS posicion\nFROM eventos_web e,\n     LATERAL FLATTEN(input =&gt; e.datos:items) f;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s10-flatten.webp\" alt=\"LATERAL FLATTEN (1) - una fila por ítem: PE A1 y B7, CO C3; la visita sin ítems no aparece (2)\" loading=\"lazy\"><figcaption>LATERAL FLATTEN (1) - una fila por ítem: PE A1 y B7, CO C3; la visita sin ítems no aparece (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Columna de FLATTEN</th>\n<th>Qué es</th>\n</tr>\n</thead><tbody><tr>\n<td><code>value</code></td>\n<td>El elemento del arreglo</td>\n</tr>\n<tr>\n<td><code>index</code></td>\n<td>Su posición, desde 0</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 Sin ítems</div>\n\n<p>La visita no aparece porque su arreglo está vacío. Para conservarla, <code>FLATTEN(input =&gt; ..., outer =&gt; TRUE)</code> devuelve una fila con <code>value</code> nulo.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Olvidar convertir con <code>::</code>.</strong> Un valor leído de VARIANT sigue siendo VARIANT y se muestra entre comillas; <code>::string</code> o <code>::number</code> lo convierten.</li>\n<li><strong>Confundir mayúsculas en las claves JSON.</strong> Las claves de VARIANT distinguen mayúsculas: <code>datos:Pais</code> no es <code>datos:pais</code>.</li>\n<li><strong>Perder filas con <code>FLATTEN</code>.</strong> Las filas con arreglo vacío desaparecen; usa <code>OUTER =&gt; TRUE</code> si las necesitas.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Guardaste JSON en VARIANT.</li>\n<li>Leíste campos anidados y convertiste tipos.</li>\n<li>Abriste arreglos en filas con FLATTEN.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-json-y-variant-ej1","opciones":[{"text":"VARCHAR(100)","ok":false},{"text":"VARIANT","ok":true},{"text":"NUMBER","ok":false},{"text":"DATE","ok":false}],"enunciado":"<p>¿Qué tipo de columna guarda JSON sin esquema fijo?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-json-y-variant-ej2","opciones":[{"text":"<code>datos:cliente.pais</code>","ok":true},{"text":"<code>datos[cliente][pais]</code> con corchetes y sin dos puntos","ok":false},{"text":"<code>JSON(datos, pais)</code>","ok":false},{"text":"<code>datos.cliente-&gt;pais</code>","ok":false}],"enunciado":"<p>¿Cómo lees el país dentro de cliente?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-json-y-variant-ej3","opciones":[{"text":"Para leer el campo solo si existe","ok":false},{"text":"Para convertir el valor VARIANT a texto","ok":true},{"text":"Para ordenar","ok":false},{"text":"Para convertir el texto en JSON","ok":false}],"enunciado":"<p>¿Para qué sirve <code>::string</code> al final?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-json-y-variant-ej4","opciones":[{"text":"Devuelve 1 fila con los 2 ítems juntos","ok":false},{"text":"Devuelve 2 filas, una por ítem, con value e index","ok":true},{"text":"Devuelve el primer ítem del arreglo","ok":false},{"text":"Da error","ok":false}],"enunciado":"<p>¿Qué hace LATERAL FLATTEN sobre un arreglo de 2 ítems?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true}]},"snowflake-paso-a-paso-merge":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Conciliar con la lista del proveedor</div>\n\n<p>MERGE compara tu tabla con la lista que llegó: lo que ya tenías y cambió se actualiza, lo nuevo se inserta, y si lo indicas, lo que sobra se borra. Todo en una sola sentencia, sin dejar la tabla a medias.</p>\n</div>\n\n\n<h2>Paso 1 — La tabla destino</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE SCHEMA tienda_dev.analitica;\nCREATE TABLE pedidos_actuales AS\nSELECT * FROM tienda_dev.raw.pedidos_staging;</code></pre>\n<h2>Paso 2 — El MERGE</h2>\n<p>Llega una corrección del pedido 90002 (el total era 95, no 80) y un pedido nuevo, el 90006:</p>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">MERGE INTO pedidos_actuales t\nUSING (SELECT 90002 AS pedido_id, 8 AS cliente_id, '2026-11-14'::date AS fecha, 'app' AS canal, 95.00 AS total\n       UNION ALL\n       SELECT 90006, 33, '2026-11-15'::date, 'web', 150.00) s\nON t.pedido_id = s.pedido_id\nWHEN MATCHED THEN UPDATE SET total = s.total\nWHEN NOT MATCHED THEN INSERT (pedido_id, cliente_id, fecha, canal, total)\n                      VALUES (s.pedido_id, s.cliente_id, s.fecha, s.canal, s.total);</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s11-merge.webp\" alt=\"El MERGE (1) y su resultado - 1 insertada, 1 actualizada, 0 borradas (2)\" loading=\"lazy\"><figcaption>El MERGE (1) y su resultado - 1 insertada, 1 actualizada, 0 borradas (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Parte</th>\n<th>Qué hace</th>\n</tr>\n</thead><tbody><tr>\n<td><code>MERGE INTO pedidos_actuales t</code></td>\n<td>La tabla que se modifica</td>\n</tr>\n<tr>\n<td><code>USING (...) s</code></td>\n<td>De dónde vienen los datos (tabla o consulta)</td>\n</tr>\n<tr>\n<td><code>ON t.pedido_id = s.pedido_id</code></td>\n<td>Cómo se emparejan</td>\n</tr>\n<tr>\n<td><code>WHEN MATCHED THEN UPDATE</code></td>\n<td>Si el pedido ya existe, lo actualiza</td>\n</tr>\n<tr>\n<td><code>WHEN NOT MATCHED THEN INSERT</code></td>\n<td>Si no existe, lo inserta</td>\n</tr>\n</tbody></table></div>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s11-resultado.webp\" alt=\"pedidos_actuales - el 90002 con total 95 y el 90006 nuevo\" loading=\"lazy\"><figcaption>pedidos_actuales - el 90002 con total 95 y el 90006 nuevo</figcaption></figure>\n\n\n<h2>Paso 3 — Más cláusulas</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">WHEN MATCHED AND s.estado = 'cancelado' THEN DELETE\nWHEN MATCHED AND t.total &lt;&gt; s.total THEN UPDATE SET total = s.total\nWHEN NOT MATCHED THEN INSERT ...</code></pre>\n<p>Para cada fila se aplica <strong>la primera cláusula que se cumple</strong>. <code>AND t.total &lt;&gt; s.total</code> evita reescribir filas que no cambiaron.</p>\n<div class=\"callout callout-cuidado\"><div class=\"callout-title\">⚠️ Una sola fila por clave en la fuente</div>\n\n<p>Si la fuente trae dos filas con el mismo <code>pedido_id</code>, Snowflake no sabe cuál usar y el MERGE puede fallar (&quot;Duplicate row detected during DML action&quot;) o dar un resultado impredecible. Deja una fila por clave antes, por ejemplo con <code>QUALIFY ROW_NUMBER() OVER (PARTITION BY pedido_id ORDER BY ...) = 1</code> (proyecto 3).</p>\n</div>\n\n\n<p><strong>Por qué es la forma correcta de cargar:</strong> si el mismo MERGE se ejecuta dos veces, el resultado es el mismo. Es <strong>idempotente</strong>, a diferencia de un <code>INSERT</code> que duplicaría filas.</p>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Fuente con claves repetidas.</strong> Dos filas del mismo pedido hacen que el MERGE falle o elija una al azar; deduplica con <code>QUALIFY ROW_NUMBER()</code>.</li>\n<li><strong>Actualizar aunque nada haya cambiado.</strong> Sin una condición extra (<code>AND t.total &lt;&gt; s.total</code>), reescribe filas idénticas.</li>\n<li><strong>Unir por una columna que no es clave.</strong> Si el <code>ON</code> no identifica una sola fila, un pedido puede actualizar varias.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Escribiste un MERGE con actualización e inserción.</li>\n<li>Lees su resultado.</li>\n<li>Conoces las cláusulas y el error de duplicados.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-merge-ej1","opciones":[{"text":"Actualiza las filas existentes","ok":false},{"text":"Inserta las filas de la fuente que no tienen pareja en el destino","ok":true},{"text":"Inserta todas las filas de la fuente, aunque ya existan","ok":false},{"text":"Actualiza las filas del destino que no vinieron en la fuente","ok":false}],"enunciado":"<p>¿Qué hace WHEN NOT MATCHED THEN INSERT?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-merge-ej2","opciones":[{"text":"Cuántas filas insertó, actualizó y borró","ok":true},{"text":"La tabla completa","ok":false},{"text":"Solo un OK","ok":false},{"text":"El plan de ejecución","ok":false}],"enunciado":"<p>¿Qué devuelve un MERGE en Snowflake?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-merge-ej3","opciones":[{"text":"Nada: el MERGE usa siempre la última fila","ok":false},{"text":"Quedarte con una fila por clave (por ejemplo con QUALIFY ROW_NUMBER)","ok":true},{"text":"Borrar el destino","ok":false},{"text":"Agrandar el warehouse para que procese las dos","ok":false}],"enunciado":"<p>La fuente trae dos filas del pedido 90002. ¿Qué haces antes del MERGE?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-merge-ej4","opciones":[{"text":"Porque es más rápido","ok":false},{"text":"Porque correrlo dos veces con los mismos datos deja el mismo resultado","ok":true},{"text":"Porque Snowflake guarda una copia antes de aplicarlo","ok":false},{"text":"Porque borra todo antes","ok":false}],"enunciado":"<p>¿Por qué un MERGE bien escrito es idempotente?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true}]},"snowflake-paso-a-paso-proyecto-carga-incremental":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El pedido</div>\n\n<p>Lucía: <em>&quot;Llegó <code>pedidos_2026_11_15.csv</code>. Trae el 90002 corregido y los pedidos 90006 y 90007. Quiero <code>pedidos_actuales</code> al día sin duplicar nada.&quot;</em></p>\n</div>\n\n\n<h2>Lo que tienes que lograr</h2>\n<ol>\n<li>Subir <code>pedidos_2026_11_15.csv</code> a <code>@carga_pedidos</code> (el archivo del día anterior sigue ahí).</li>\n<li>Cargarlo a <code>raw.pedidos_staging</code> con COPY INTO sin recargar el anterior.</li>\n<li>MERGE a <code>analitica.pedidos_actuales</code> con una fila por pedido, actualizando solo si cambió el total.</li>\n<li>Comprobar que quedan 7 pedidos y el 90002 con total 95.</li>\n</ol>\n<details><summary>💡 Pista 1: ¿y el archivo de ayer?</summary>\n\n<p>COPY INTO guarda qué archivos ya cargó en cada tabla (durante 64 días) y los saltea. No hace falta moverlos ni borrarlos. Para forzar una recarga existe <code>FORCE = TRUE</code>, con cuidado de no duplicar.</p>\n</details>\n\n<details><summary>💡 Pista 2: el staging tiene el 90002 dos veces</summary>\n\n<p>El staging acumula las dos versiones del 90002. Antes del MERGE, deja una fila por pedido con <code>QUALIFY ROW_NUMBER() OVER (PARTITION BY pedido_id ORDER BY ...) = 1</code>.</p>\n</details>\n\n<h2>Cómo se ve terminado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s12-copy.webp\" alt=\"COPY INTO - el archivo del 14 en LOAD_SKIPPED (ya cargado) y el del 15 en LOADED con 3 filas\" loading=\"lazy\"><figcaption>COPY INTO - el archivo del 14 en LOAD_SKIPPED (ya cargado) y el del 15 en LOADED con 3 filas</figcaption></figure>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s12-merge.webp\" alt=\"El MERGE con la fuente deduplicada (1) - 1 pedido insertado (2)\" loading=\"lazy\"><figcaption>El MERGE con la fuente deduplicada (1) - 1 pedido insertado (2)</figcaption></figure>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s12-final.webp\" alt=\"pedidos_actuales con los 7 pedidos\" loading=\"lazy\"><figcaption>pedidos_actuales con los 7 pedidos</figcaption></figure>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Forzar la recarga con <code>FORCE = TRUE</code> sin pensar.</strong> COPY INTO saltea los archivos ya cargados para no duplicar; forzarla duplica filas.</li>\n<li><strong>No deduplicar la fuente.</strong> Si el archivo trae dos versiones del mismo pedido, el MERGE falla o queda impredecible.</li>\n<li><strong>Probar una sola vez.</strong> La carga incremental se valida corriéndola dos veces: la segunda no debe cambiar nada.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lista de verificación</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  El resultado de COPY INTO muestra el archivo del 14 como LOAD_SKIPPED.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  <code>pedidos_actuales</code> tiene 7 filas, una por pedido.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  El 90002 tiene total 95.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Correr el COPY INTO y el MERGE otra vez no cambia nada.</li>\n</ul>\n<details><summary>💡 Solución comentada</summary>\n\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE SCHEMA tienda_dev.raw;\nCOPY INTO pedidos_staging\nFROM @carga_pedidos\nFILE_FORMAT = (TYPE = CSV SKIP_HEADER = 1);\n\nUSE SCHEMA tienda_dev.analitica;\nMERGE INTO pedidos_actuales t\nUSING (SELECT * FROM tienda_dev.raw.pedidos_staging\n       QUALIFY ROW_NUMBER() OVER (PARTITION BY pedido_id ORDER BY total DESC) = 1) s\nON t.pedido_id = s.pedido_id\nWHEN MATCHED AND t.total &lt;&gt; s.total THEN UPDATE SET total = s.total\nWHEN NOT MATCHED THEN INSERT (pedido_id, cliente_id, fecha, canal, total)\n                      VALUES (s.pedido_id, s.cliente_id, s.fecha, s.canal, s.total);</code></pre>\n<p>El MERGE da <strong>1 insertada, 0 actualizadas</strong>: el 90006 y la corrección del 90002 ya estaban del ejercicio anterior, y solo falta el 90007. Es justo lo que se busca: <strong>correrlo de nuevo no cambia nada</strong>.</p>\n<p><strong>Mejora para producción:</strong> ordenar por una columna de &quot;cuándo llegó&quot; (por ejemplo <code>METADATA$FILE_LAST_MODIFIED</code> o una fecha de carga) en lugar de por <code>total</code>, para quedarte siempre con la versión más reciente.</p>\n</details>\n\n<h2>Lo que aprendiste en el nivel 3</h2>\n<ul>\n<li>Stages y COPY INTO.</li>\n<li>JSON con VARIANT y FLATTEN.</li>\n<li>MERGE e ingesta incremental.</li>\n</ul>\n<p>En el nivel 4: Time Travel, UNDROP, clones y SQL analítico.</p>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-carga-incremental-ej1","opciones":[{"text":"Lo carga de nuevo y duplica","ok":false},{"text":"Lo saltea (LOAD_SKIPPED) gracias a su historial de cargas","ok":true},{"text":"Lo borra del stage","ok":false},{"text":"Da error","ok":false}],"enunciado":"<p>¿Qué hace COPY INTO con un archivo que ya cargó en esa tabla?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-carga-incremental-ej2","opciones":[{"text":"Porque si una clave aparece dos veces el MERGE puede fallar o ser impredecible","ok":true},{"text":"Porque así COPY INTO carga más rápido","ok":false},{"text":"Porque COPY INTO lo exige","ok":false},{"text":"No hace falta","ok":false}],"enunciado":"<p>¿Por qué se deduplica la fuente antes del MERGE?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-carga-incremental-ej3","opciones":[{"text":"Borra los que cambiaron","ok":false},{"text":"Actualiza solo los pedidos cuyo total cambió","ok":true},{"text":"Inserta duplicados","ok":false},{"text":"Inserta una fila nueva por cada cambio de total","ok":false}],"enunciado":"<p>¿Qué logra <code>WHEN MATCHED AND t.total &lt;&gt; s.total</code>?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-carga-incremental-ej4","opciones":[{"text":"1 hora","ok":false},{"text":"7 días","ok":false},{"text":"64 días","ok":true},{"text":"Para siempre","ok":false}],"enunciado":"<p>¿Cuánto tiempo recuerda COPY INTO qué archivos cargó?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true}]},"snowflake-paso-a-paso-time-travel":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El incidente</div>\n\n<p>Un viernes a las 18:00, alguien prueba un <code>DELETE</code> en la hoja equivocada:</p>\n</div>\n\n\n<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Volver al minuto anterior al error</div>\n\n<p>Time Travel es poder mirar la tabla como estaba antes de un momento exacto. Lo más preciso no es &quot;hace una hora&quot; sino &quot;justo antes de esta sentencia&quot;: con el Query ID del <code>DELETE</code> vuelves al instante anterior sin adivinar horarios.</p>\n</div>\n\n\n<h2>Paso 1 — El error</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE SCHEMA tienda_dev.analitica;\n-- ¡sin WHERE! borra todos los pedidos\nDELETE FROM pedidos_actuales;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s13-delete.webp\" alt=\"El DELETE sin WHERE (1) - 7 filas borradas - y su Query ID en Query Details (2)\" loading=\"lazy\"><figcaption>El DELETE sin WHERE (1) - 7 filas borradas - y su Query ID en Query Details (2)</figcaption></figure>\n\n\n<p>Copia el <strong>Query ID</strong> del DELETE (de Query Details o de Query History).</p>\n<h2>Paso 2 — Mirar el pasado</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT * FROM pedidos_actuales BEFORE(STATEMENT =&gt; '01b0...-0046') ORDER BY pedido_id;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s13-before.webp\" alt=\"BEFORE(STATEMENT =&gt; ...) (1) - los 7 pedidos tal como estaban justo antes del DELETE (2)\" loading=\"lazy\"><figcaption>BEFORE(STATEMENT =&gt; ...) (1) - los 7 pedidos tal como estaban justo antes del DELETE (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Forma</th>\n<th>Qué devuelve</th>\n</tr>\n</thead><tbody><tr>\n<td><code>AT(OFFSET =&gt; -60*5)</code></td>\n<td>La tabla hace 5 minutos</td>\n</tr>\n<tr>\n<td><code>AT(TIMESTAMP =&gt; &#39;2026-11-15 17:55:00&#39;::timestamp_tz)</code></td>\n<td>La tabla en ese instante</td>\n</tr>\n<tr>\n<td><code>BEFORE(STATEMENT =&gt; &#39;&lt;query id&gt;&#39;)</code></td>\n<td>La tabla justo antes de esa sentencia: lo más preciso</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 3 — Restaurar</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">INSERT INTO pedidos_actuales\nSELECT * FROM pedidos_actuales BEFORE(STATEMENT =&gt; '01b0...-0046');\n\nSELECT COUNT(*) AS recuperados FROM pedidos_actuales;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s13-restaurado.webp\" alt=\"El INSERT desde el pasado (1) y los 7 pedidos recuperados (2)\" loading=\"lazy\"><figcaption>El INSERT desde el pasado (1) y los 7 pedidos recuperados (2)</figcaption></figure>\n\n\n<h2>Paso 4 — Cuánto dura</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Concepto</th>\n<th>Duración</th>\n<th>Quién lo usa</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Time Travel</strong></td>\n<td>1 día por defecto; hasta 90 días en Enterprise (<code>DATA_RETENTION_TIME_IN_DAYS</code>)</td>\n<td>Tú, con SQL</td>\n</tr>\n<tr>\n<td><strong>Fail-safe</strong></td>\n<td>7 días después de Time Travel (solo tablas permanentes)</td>\n<td>Solo el soporte de Snowflake, para desastres</td>\n</tr>\n</tbody></table></div>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">ALTER TABLE pedidos_actuales SET DATA_RETENTION_TIME_IN_DAYS = 7;</code></pre>\n<div class=\"callout callout-cuidado\"><div class=\"callout-title\">⚠️ No es un backup gratis</div>\n\n<p>Cada versión anterior ocupa almacenamiento mientras dure la retención. Más días de Time Travel = más costo de almacenamiento en tablas que cambian mucho.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Esperar demasiado.</strong> Por defecto la retención es de 1 día; pasado ese plazo los datos solo quedan en Fail-safe, que solo recupera el soporte de Snowflake.</li>\n<li><strong>Restaurar con <code>INSERT</code> sobre una tabla que no quedó vacía.</strong> Duplicas filas; en ese caso reemplaza la tabla con <code>CREATE OR REPLACE ... AS SELECT ... BEFORE(...)</code>.</li>\n<li><strong>Adivinar la hora con OFFSET.</strong> Si te equivocas por segundos, recuperas una versión ya rota; usa <code>BEFORE(STATEMENT =&gt; ...)</code>.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Consultaste una tabla en el pasado.</li>\n<li>Recuperaste un DELETE con el Query ID.</li>\n<li>Conoces la retención y Fail-safe.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-time-travel-ej1","opciones":[{"text":"AT(OFFSET =&gt; -3600)","ok":false},{"text":"BEFORE(STATEMENT =&gt; &#39;<query id del error>&#39;)","ok":true},{"text":"AT(TIMESTAMP =&gt; CURRENT_TIMESTAMP())","ok":false},{"text":"UNDROP TABLE","ok":false}],"enunciado":"<p>¿Cuál es la forma más precisa de ver la tabla justo antes de un error?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-time-travel-ej2","opciones":[{"text":"1 día","ok":true},{"text":"7 días","ok":false},{"text":"90 días","ok":false},{"text":"Para siempre","ok":false}],"enunciado":"<p>¿Cuánto dura Time Travel por defecto?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-time-travel-ej3","opciones":[{"text":"Cualquier usuario con SELECT","ok":false},{"text":"El ACCOUNTADMIN con SQL","ok":false},{"text":"Solo el soporte de Snowflake","ok":true},{"text":"Cualquier rol con OWNERSHIP sobre la tabla","ok":false}],"enunciado":"<p>¿Quién puede recuperar datos desde Fail-safe?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-time-travel-ej4","opciones":[{"text":"En Marketplace","ok":false},{"text":"En Query Details del resultado o en Query History","ok":true},{"text":"En SHOW TABLES, en la columna comment","ok":false},{"text":"En Warehouses","ok":false}],"enunciado":"<p>¿Dónde encuentras el Query ID de la sentencia que borró los datos?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true}]},"snowflake-paso-a-paso-undrop-y-clones":{"html":"<h2>Paso 1 — UNDROP</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE SCHEMA tienda_dev.analitica;\nDROP TABLE ventas_por_canal;\nUNDROP TABLE ventas_por_canal;\nSELECT * FROM ventas_por_canal;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s14-undrop.webp\" alt=\"DROP y UNDROP (1) - la tabla vuelve con sus 4 filas (2)\" loading=\"lazy\"><figcaption>DROP y UNDROP (1) - la tabla vuelve con sus 4 filas (2)</figcaption></figure>\n\n\n<p><code>UNDROP</code> funciona mientras la tabla esté dentro de su retención de Time Travel. También existe <code>UNDROP SCHEMA</code> y <code>UNDROP DATABASE</code>.</p>\n<h2>Paso 2 — Clonar una base</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE DATABASE tienda_qa CLONE tienda_dev;\nSHOW SCHEMAS IN DATABASE tienda_qa;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s14-clone.webp\" alt=\"TIENDA_QA en el explorador con las mismas tablas (1) y sus esquemas (2)\" loading=\"lazy\"><figcaption>TIENDA_QA en el explorador con las mismas tablas (1) y sus esquemas (2)</figcaption></figure>\n\n\n<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Zero-copy clone</div>\n\n<p>Un clon es como una fotocopia que <strong>no gasta papel</strong> hasta que la escribes: al crearlo comparte las mismas micro-particiones que el original, así que no ocupa almacenamiento extra ni tarda aunque la base tenga terabytes. Solo lo que cambies en el clon (o en el original) después ocupa espacio nuevo.</p>\n</div>\n\n\n<h2>Paso 3 — Para qué sirve</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Uso</th>\n<th>Cómo</th>\n</tr>\n</thead><tbody><tr>\n<td>Probar un cambio sin riesgo</td>\n<td><code>CREATE DATABASE tienda_qa CLONE tienda_prod;</code> y probar ahí</td>\n</tr>\n<tr>\n<td>Entorno de QA con datos reales</td>\n<td>Un clon nuevo cada mañana</td>\n</tr>\n<tr>\n<td>Analizar &quot;cómo estaba ayer&quot;</td>\n<td><code>CREATE TABLE pedidos_ayer CLONE pedidos AT(OFFSET =&gt; -86400);</code></td>\n</tr>\n<tr>\n<td>Copia de seguridad antes de una migración</td>\n<td>Clonar la tabla antes de tocarla</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-cuidado\"><div class=\"callout-title\">⚠️ Los clones no copian todo</div>\n\n<p>Un clon de base o esquema copia tablas, vistas y otros objetos, y los permisos sobre los objetos hijos; pero no copia los stages internos con sus archivos, ni el historial de cargas de COPY INTO. Revisa la documentación antes de clonar producción.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong><code>UNDROP</code> cuando ya existe otra tabla con ese nombre.</strong> Falla; renombra la tabla nueva antes de recuperar la borrada.</li>\n<li><strong>Creer que un clon es una vista.</strong> Es una tabla independiente: lo que cambies en el clon no toca el original.</li>\n<li><strong>Dejar clones viejos para siempre.</strong> Al principio no ocupan espacio, pero cada cambio sobre el clon o el original va sumando almacenamiento propio.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Recuperaste una tabla con UNDROP.</li>\n<li>Clonaste una base entera.</li>\n<li>Sabes cuándo usar clones.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-undrop-y-clones-ej1","opciones":[{"text":"Borra la tabla para siempre","ok":false},{"text":"Recupera una tabla borrada mientras esté dentro de la retención de Time Travel","ok":true},{"text":"Clona la tabla","ok":false},{"text":"Recupera la tabla desde Fail-safe, sin límite de tiempo","ok":false}],"enunciado":"<p>¿Qué hace UNDROP TABLE?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-undrop-y-clones-ej2","opciones":[{"text":"Prácticamente nada: comparte las micro-particiones del original","ok":true},{"text":"El doble de la base","ok":false},{"text":"Lo mismo que el original","ok":false},{"text":"La mitad del original, por la compresión","ok":false}],"enunciado":"<p>¿Cuánto almacenamiento extra ocupa un clon recién creado?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-undrop-y-clones-ej3","opciones":[{"text":"<code>UNDROP pedidos AT(OFFSET =&gt; -86400)</code>","ok":false},{"text":"<code>CREATE TABLE pedidos_ayer CLONE pedidos AT(OFFSET =&gt; -86400);</code>","ok":true},{"text":"<code>COPY INTO pedidos_ayer</code>","ok":false},{"text":"<code>UNDROP pedidos</code>","ok":false}],"enunciado":"<p>¿Cómo creas una copia de la tabla como estaba hace un día?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-undrop-y-clones-ej4","opciones":[{"text":"La pruebas en producción","ok":false},{"text":"La pruebas en un clon de la base","ok":true},{"text":"La pruebas en producción, de noche y con un backup","ok":false},{"text":"La pruebas en una vista de la base","ok":false}],"enunciado":"<p>Quieres probar una migración riesgosa con datos reales. ¿Qué haces?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true}]},"snowflake-paso-a-paso-sql-analitico":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Numerar y quedarse con el primero</div>\n\n<p><code>QUALIFY</code> filtra por el resultado de una función de ventana: primero numeras los pedidos de cada cliente del más nuevo al más viejo, y después te quedas con el número 1. Es el <code>HAVING</code> de las ventanas.</p>\n</div>\n\n\n<h2>Paso 1 — QUALIFY</h2>\n<p>El último pedido de cada cliente:</p>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT cliente_id, pedido_id, fecha_pedido, canal\nFROM pedidos\nQUALIFY ROW_NUMBER() OVER (PARTITION BY cliente_id ORDER BY fecha_pedido DESC, pedido_id DESC) = 1\nORDER BY cliente_id\nLIMIT 10;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s15-qualify.webp\" alt=\"QUALIFY con ROW_NUMBER (1) - una fila por cliente con su último pedido (2)\" loading=\"lazy\"><figcaption>QUALIFY con ROW_NUMBER (1) - una fila por cliente con su último pedido (2)</figcaption></figure>\n\n\n<p><strong>QUALIFY</strong> es a las funciones de ventana lo que <code>HAVING</code> es a <code>GROUP BY</code>: filtra después de calcularlas. Sin QUALIFY habría que envolver la consulta en una subconsulta y filtrar afuera.</p>\n<h2>Paso 2 — Ventanas: variación mensual</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">WITH mensual AS (\n  SELECT DATE_TRUNC('month', fecha_pedido) AS mes, COUNT(*) AS pedidos\n  FROM pedidos\n  GROUP BY 1\n)\nSELECT mes, pedidos,\n       pedidos - LAG(pedidos) OVER (ORDER BY mes) AS variacion\nFROM mensual\nORDER BY mes DESC\nLIMIT 12;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s15-ventana.webp\" alt=\"La CTE con LAG (1) y los pedidos por mes con la diferencia contra el mes anterior (2)\" loading=\"lazy\"><figcaption>La CTE con LAG (1) y los pedidos por mes con la diferencia contra el mes anterior (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Función</th>\n<th>Devuelve</th>\n</tr>\n</thead><tbody><tr>\n<td><code>LAG(x)</code> / <code>LEAD(x)</code></td>\n<td>El valor de la fila anterior / siguiente</td>\n</tr>\n<tr>\n<td><code>ROW_NUMBER()</code>, <code>RANK()</code></td>\n<td>La posición dentro de la partición</td>\n</tr>\n<tr>\n<td><code>SUM(x) OVER (ORDER BY mes)</code></td>\n<td>Acumulado</td>\n</tr>\n<tr>\n<td><code>AVG(x) OVER (ORDER BY mes ROWS 2 PRECEDING)</code></td>\n<td>Media móvil de 3 meses</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 3 — Muestreo y funciones útiles</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">-- 10 % de las filas, al azar: para explorar sin leer toda la tabla\nSELECT * FROM pedidos SAMPLE (10);</code></pre>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Función</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><code>IFF(cond, a, b)</code></td>\n<td>Un <code>CASE</code> corto</td>\n</tr>\n<tr>\n<td><code>NVL(x, 0)</code>, <code>ZEROIFNULL(x)</code></td>\n<td>Reemplazar nulos</td>\n</tr>\n<tr>\n<td><code>DATEADD(day, -7, fecha)</code> / <code>DATEDIFF(day, a, b)</code></td>\n<td>Sumar y restar fechas</td>\n</tr>\n<tr>\n<td><code>TRY_TO_NUMBER(x)</code></td>\n<td>Convertir sin fallar (devuelve NULL si no puede)</td>\n</tr>\n<tr>\n<td><code>ARRAY_AGG(x)</code>, <code>OBJECT_CONSTRUCT(...)</code></td>\n<td>Armar arreglos y JSON</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Filtrar la ventana en el <code>WHERE</code>.</strong> El <code>WHERE</code> se evalúa antes y da error; el filtro va en <code>QUALIFY</code>.</li>\n<li><strong>Usar <code>SAMPLE</code> para resultados exactos.</strong> Es una muestra al azar: sirve para explorar, no para informar totales.</li>\n<li><strong>Convertir con <code>TO_NUMBER</code> datos sucios.</strong> Falla con el primer valor inválido; <code>TRY_TO_NUMBER</code> devuelve NULL.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Filtraste con QUALIFY.</li>\n<li>Calculaste variaciones con LAG.</li>\n<li>Conoces SAMPLE y funciones propias de Snowflake.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-sql-analitico-ej1","opciones":[{"text":"Filas antes de agrupar","ok":false},{"text":"Grupos después de GROUP BY","ok":false},{"text":"Filas según el resultado de una función de ventana","ok":true},{"text":"Columnas","ok":false}],"enunciado":"<p>¿Qué filtra QUALIFY?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-sql-analitico-ej2","opciones":[{"text":"El número de pedidos del mes anterior","ok":true},{"text":"El del mes siguiente","ok":false},{"text":"El total de todos los meses","ok":false},{"text":"El promedio de los meses anteriores","ok":false}],"enunciado":"<p>¿Qué devuelve LAG(pedidos) OVER (ORDER BY mes)?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-sql-analitico-ej3","opciones":[{"text":"Para leer el 10 % más reciente de la tabla","ok":false},{"text":"Para leer una muestra al azar del 10 % de las filas","ok":true},{"text":"Para limitar a 10 filas exactas","ok":false},{"text":"Para leer las primeras 10 micro-particiones","ok":false}],"enunciado":"<p>¿Para qué sirve SAMPLE (10)?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-sql-analitico-ej4","opciones":[{"text":"Un error","ok":false},{"text":"0","ok":false},{"text":"NULL","ok":true},{"text":"&#39;abc&#39;","ok":false}],"enunciado":"<p>¿Qué devuelve TRY_TO_NUMBER(&#39;abc&#39;)?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true}]},"snowflake-paso-a-paso-proyecto-incidente-del-update":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El incidente</div>\n\n<p>Finanzas: <em>&quot;El tablero muestra ventas en 0. ¿Qué pasó? Necesitamos los números de vuelta antes de la reunión.&quot;</em></p>\n</div>\n\n\n<h2>Lo que tienes que lograr</h2>\n<ol>\n<li>Encontrar en Query History la sentencia que dejó los totales en 0.</li>\n<li>Restaurar <code>pedidos_actuales</code> a como estaba justo antes.</li>\n<li>Comprobar que los totales volvieron (el 90004 vale 310).</li>\n<li>Escribir una propuesta de una línea para que no se repita.</li>\n</ol>\n<h2>Cómo se ve terminado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s16-error.webp\" alt=\"El UPDATE sin WHERE (1) - 7 filas actualizadas (2)\" loading=\"lazy\"><figcaption>El UPDATE sin WHERE (1) - 7 filas actualizadas (2)</figcaption></figure>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s16-recuperado.webp\" alt=\"La tabla restaurada con BEFORE (1) y los totales correctos (2)\" loading=\"lazy\"><figcaption>La tabla restaurada con BEFORE (1) y los totales correctos (2)</figcaption></figure>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Restaurar con <code>INSERT</code> sobre la tabla dañada.</strong> Las filas siguen ahí con valores malos; se duplican. Reemplaza la tabla con la versión anterior.</li>\n<li><strong>Corregir sin encontrar la causa.</strong> Sin la sentencia del historial no sabes qué más pudo romperse.</li>\n<li><strong>No cambiar nada después.</strong> Sin un rol de solo lectura y pruebas en un clon, el incidente se repite.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lista de verificación</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Tienes el Query ID del UPDATE.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  <code>SELECT pedido_id, total FROM pedidos_actuales</code> muestra los totales originales.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Tienes la propuesta.</li>\n</ul>\n<details><summary>💡 Solución comentada</summary>\n\n<ol>\n<li><strong>Query History</strong>: buscar un <code>UPDATE pedidos_actuales SET total = 0</code> reciente y copiar su Query ID.</li>\n<li>Restaurar:</li>\n</ol>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE OR REPLACE TABLE pedidos_actuales AS\nSELECT * FROM pedidos_actuales BEFORE(STATEMENT =&gt; '&lt;query id del UPDATE&gt;');</code></pre>\n<p><strong>Por qué CREATE OR REPLACE y no INSERT:</strong> el UPDATE no borró filas, las <strong>cambió</strong>. Insertar las versiones anteriores duplicaría los pedidos; reemplazar la tabla deja exactamente el estado anterior. (Si después del error hubo cambios buenos, hay que rescatarlos aparte o usar un MERGE desde el pasado.)</p>\n<p><strong>Propuestas para prevenirlo:</strong></p>\n<ul>\n<li>Probar los cambios en un <strong>clon</strong> (<code>CREATE TABLE pedidos_prueba CLONE pedidos_actuales;</code>) antes de tocar la tabla real.</li>\n<li>Que los analistas tengan solo <code>SELECT</code> sobre <code>analitica</code> (nivel 5): un rol que no puede escribir no puede romper.</li>\n<li>Siempre correr primero un <code>SELECT ... WHERE ...</code> con la misma condición del UPDATE para ver qué filas toca.</details></li>\n</ul>\n<h2>Lo que aprendiste en el nivel 4</h2>\n<ul>\n<li>Time Travel con AT y BEFORE.</li>\n<li>UNDROP y zero-copy clones.</li>\n<li>QUALIFY, ventanas y SAMPLE.</li>\n</ul>\n<p>En el nivel 5: roles, permisos y costos.</p>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-incidente-del-update-ej1","opciones":[{"text":"INSERT de la versión anterior","ok":false},{"text":"CREATE OR REPLACE TABLE ... AS SELECT de la versión anterior con BEFORE","ok":true},{"text":"UNDROP TABLE","ok":false},{"text":"TRUNCATE y volver a cargar los archivos del stage","ok":false}],"enunciado":"<p>Un UPDATE cambió todos los totales. ¿Cómo restauras sin duplicar filas?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-incidente-del-update-ej2","opciones":[{"text":"Query History","ok":true},{"text":"Marketplace","ok":false},{"text":"Warehouses","ok":false},{"text":"Copy History","ok":false}],"enunciado":"<p>¿Dónde encuentras la sentencia que causó el problema?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-incidente-del-update-ej3","opciones":[{"text":"Darle ACCOUNTADMIN","ok":false},{"text":"Darle un rol con solo SELECT sobre lo que necesita","ok":true},{"text":"Apagar el warehouse","ok":false},{"text":"Agrandar el warehouse","ok":false}],"enunciado":"<p>¿Qué práctica evita que un analista rompa una tabla por error?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-incidente-del-update-ej4","opciones":[{"text":"Nada","ok":false},{"text":"Un SELECT con la misma condición para ver qué filas va a tocar","ok":true},{"text":"Un SHOW TABLES para ver si la tabla existe","ok":false},{"text":"Un COPY INTO","ok":false}],"enunciado":"<p>¿Qué conviene correr antes de un UPDATE con WHERE?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true}]},"snowflake-paso-a-paso-roles":{"html":"<h2>Paso 1 — El modelo</h2>\n<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Llaves y llaveros</div>\n\n<p>Los <strong>permisos</strong> son llaves (leer esta tabla, usar este warehouse). Un <strong>rol</strong> es un llavero con varias llaves. Un <strong>usuario</strong> recibe uno o más llaveros y en cada sesión usa uno. Nunca se dan llaves sueltas a una persona: se agregan al llavero y se entrega el llavero.</p>\n</div>\n\n\n<p><strong>Admin → Users &amp; Roles</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s17-roles.webp\" alt=\"Los roles del sistema con su descripción\" loading=\"lazy\"><figcaption>Los roles del sistema con su descripción</figcaption></figure>\n\n\n<h2>Paso 2 — Los roles del sistema</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Rol</th>\n<th>Para</th>\n<th>Hereda</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>ACCOUNTADMIN</strong></td>\n<td>Todo, incluida facturación y resource monitors</td>\n<td>SYSADMIN y SECURITYADMIN</td>\n</tr>\n<tr>\n<td><strong>SECURITYADMIN</strong></td>\n<td>Administrar permisos (GRANT) y usuarios</td>\n<td>USERADMIN</td>\n</tr>\n<tr>\n<td><strong>USERADMIN</strong></td>\n<td>Crear usuarios y roles</td>\n<td>-</td>\n</tr>\n<tr>\n<td><strong>SYSADMIN</strong></td>\n<td>Crear warehouses, bases y objetos: el rol de ingeniería</td>\n<td>Los roles propios que se le asignan</td>\n</tr>\n<tr>\n<td><strong>PUBLIC</strong></td>\n<td>Lo que tienen todos los usuarios</td>\n<td>-</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-cuidado\"><div class=\"callout-title\">⚠️ ACCOUNTADMIN lo menos posible</div>\n\n<p>Es el rol más poderoso: puede cambiar la facturación y ver todo. Úsalo solo para tareas de cuenta, con MFA, y que lo tengan pocas personas. El trabajo diario de ingeniería se hace con SYSADMIN o un rol propio.</p>\n</div>\n\n\n<p>Buena práctica: los roles propios (por ejemplo <code>analista_ventas</code>) se asignan a SYSADMIN, así SYSADMIN puede administrar los objetos que esos roles creen.</p>\n<h2>Paso 3 — Cambiar de rol</h2>\n<p>Menú del usuario (abajo a la izquierda) → <strong>Switch Role</strong>, o <code>USE ROLE</code>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s17-cambiar.webp\" alt=\"El menú del usuario - Switch Role con los roles disponibles\" loading=\"lazy\"><figcaption>El menú del usuario - Switch Role con los roles disponibles</figcaption></figure>\n\n\n<h2>Paso 4 — Sin permiso</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE ROLE PUBLIC;\nSELECT COUNT(*) FROM tienda_dev.analitica.pedidos_actuales;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s17-sin-permiso.webp\" alt=\"El rol actual PUBLIC (1) y el error - does not exist or not authorized, con lo que le falta (2)\" loading=\"lazy\"><figcaption>El rol actual PUBLIC (1) y el error - does not exist or not authorized, con lo que le falta (2)</figcaption></figure>\n\n\n<p>Para leer una tabla, un rol necesita <strong>tres</strong> permisos: <code>USAGE</code> en la base, <code>USAGE</code> en el esquema y <code>SELECT</code> en la tabla (además de <code>USAGE</code> en un warehouse para ejecutar). Los das en la próxima lección.</p>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Trabajar todo el día como ACCOUNTADMIN.</strong> Cualquier error tiene el máximo alcance, incluida la facturación.</li>\n<li><strong>Dar solo <code>SELECT</code> en la tabla.</strong> Sin <code>USAGE</code> en la base y en el esquema, el rol no llega a la tabla.</li>\n<li><strong>Dar permisos a usuarios.</strong> En Snowflake se dan a roles; el usuario recibe roles.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Entiendes el modelo de roles.</li>\n<li>Conoces los roles del sistema y su jerarquía.</li>\n<li>Interpretas un error de permisos.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-roles-ej1","opciones":[{"text":"Directamente a los usuarios","ok":false},{"text":"A roles, y los roles a usuarios","ok":true},{"text":"A los warehouses","ok":false},{"text":"A los esquemas, que los heredan los usuarios","ok":false}],"enunciado":"<p>¿A quién se dan los permisos en Snowflake?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-roles-ej2","opciones":[{"text":"ACCOUNTADMIN","ok":false},{"text":"SYSADMIN (o un rol propio)","ok":true},{"text":"PUBLIC","ok":false},{"text":"USERADMIN","ok":false}],"enunciado":"<p>¿Qué rol se usa para el trabajo diario de ingeniería (crear bases, tablas, warehouses)?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-roles-ej3","opciones":[{"text":"Solo SELECT en la tabla","ok":false},{"text":"USAGE en la base, USAGE en el esquema y SELECT en la tabla","ok":true},{"text":"OWNERSHIP de la cuenta","ok":false},{"text":"USAGE en el warehouse y nada más","ok":false}],"enunciado":"<p>¿Qué permisos necesita un rol para leer una tabla?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-roles-ej4","opciones":[{"text":"Porque sus consultas no usan la caché","ok":false},{"text":"Porque es el rol más poderoso, incluida la facturación","ok":true},{"text":"Porque no puede leer datos","ok":false},{"text":"Porque cuesta más créditos","ok":false}],"enunciado":"<p>¿Por qué ACCOUNTADMIN se usa lo menos posible?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true}]},"snowflake-paso-a-paso-grants":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El pedido</div>\n\n<p>Comercial: <em>&quot;Necesitamos consultar <code>analitica</code> desde Snowsight y Power BI. No queremos tocar nada, solo leer.&quot;</em></p>\n</div>\n\n\n<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Armar un llavero</div>\n\n<p>Crear un rol es armar un llavero: le agregas la llave del warehouse (para poder trabajar), la de la base y el esquema (para entrar) y la de las tablas (para leer). Después le das el llavero a una persona. Si falta una llave del camino, no llega.</p>\n</div>\n\n\n<h2>Paso 1 — El rol y sus permisos</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE ROLE SECURITYADMIN;\nCREATE ROLE analista_ventas;\nGRANT USAGE ON WAREHOUSE analisis_wh TO ROLE analista_ventas;\nGRANT USAGE ON DATABASE tienda_dev TO ROLE analista_ventas;\nGRANT USAGE ON SCHEMA tienda_dev.analitica TO ROLE analista_ventas;\nGRANT SELECT ON ALL TABLES IN SCHEMA tienda_dev.analitica TO ROLE analista_ventas;\nGRANT ROLE analista_ventas TO USER alumno;\nSHOW GRANTS TO ROLE analista_ventas;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s18-grants.webp\" alt=\"El script de permisos (1) y SHOW GRANTS - USAGE en el warehouse, la base y el esquema, y SELECT en todas las tablas (2)\" loading=\"lazy\"><figcaption>El script de permisos (1) y SHOW GRANTS - USAGE en el warehouse, la base y el esquema, y SELECT en todas las tablas (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Permiso</th>\n<th>Sobre</th>\n<th>Permite</th>\n</tr>\n</thead><tbody><tr>\n<td><code>USAGE</code></td>\n<td>Warehouse</td>\n<td>Ejecutar consultas con él</td>\n</tr>\n<tr>\n<td><code>USAGE</code></td>\n<td>Base / esquema</td>\n<td>&quot;Entrar&quot; para ver lo que hay adentro</td>\n</tr>\n<tr>\n<td><code>SELECT</code></td>\n<td>Tabla / vista</td>\n<td>Leer</td>\n</tr>\n<tr>\n<td><code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code></td>\n<td>Tabla</td>\n<td>Escribir</td>\n</tr>\n<tr>\n<td><code>CREATE TABLE</code></td>\n<td>Esquema</td>\n<td>Crear tablas</td>\n</tr>\n<tr>\n<td><code>OWNERSHIP</code></td>\n<td>Objeto</td>\n<td>Ser dueño (todo, incluido darlo a otros)</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — Probarlo</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE ROLE analista_ventas;\nUSE WAREHOUSE analisis_wh;\nSELECT canal, COUNT(*) AS pedidos, SUM(total) AS ventas\nFROM tienda_dev.analitica.pedidos_actuales\nGROUP BY canal;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s18-analista.webp\" alt=\"Con el rol ANALISTA_VENTAS (1) la consulta funciona (2)\" loading=\"lazy\"><figcaption>Con el rol ANALISTA_VENTAS (1) la consulta funciona (2)</figcaption></figure>\n\n\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">DELETE FROM tienda_dev.analitica.pedidos_actuales;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s18-no-puede.webp\" alt=\"Insufficient privileges - falta GRANT DELETE: el rol solo puede leer\" loading=\"lazy\"><figcaption>Insufficient privileges - falta GRANT DELETE: el rol solo puede leer</figcaption></figure>\n\n\n<h2>Paso 3 — Tablas futuras</h2>\n<p><code>ALL TABLES</code> da permiso sobre las tablas que <strong>ya existen</strong>. Las que se creen mañana no quedan incluidas. Para eso:</p>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">GRANT SELECT ON FUTURE TABLES IN SCHEMA tienda_dev.analitica TO ROLE analista_ventas;</code></pre>\n<h2>Paso 4 — Quitar</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">REVOKE SELECT ON ALL TABLES IN SCHEMA tienda_dev.analitica FROM ROLE analista_ventas;</code></pre>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 Mínimo privilegio</div>\n\n<p>Da el rol más chico que alcance para el trabajo. Los analistas leen <code>analitica</code>; las cargas escriben en <code>raw</code>; nadie tiene ACCOUNTADMIN para trabajar.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Olvidar las tablas futuras.</strong> <code>ON ALL TABLES</code> cubre las que existen hoy; para las nuevas hace falta <code>ON FUTURE TABLES</code>.</li>\n<li><strong>Dar permisos con el rol del analista.</strong> Los roles y grants se administran con SECURITYADMIN (o USERADMIN para crear usuarios y roles).</li>\n<li><strong>No probar el rol.</strong> Hay que usarlo y comprobar que puede lo que debe y no puede lo que no debe.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Creaste un rol de solo lectura.</li>\n<li>Lo probaste: lee pero no borra.</li>\n<li>Conoces FUTURE GRANTS y REVOKE.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-grants-ej1","opciones":[{"text":"ACCOUNTADMIN, para cualquier permiso","ok":false},{"text":"SYSADMIN","ok":false},{"text":"SECURITYADMIN (o USERADMIN para crear)","ok":true},{"text":"El rol del analista","ok":false}],"enunciado":"<p>¿Con qué rol del sistema conviene crear roles y dar permisos?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-grants-ej2","opciones":[{"text":"<code>GRANT SELECT ON ALL TABLES IN SCHEMA ... TO ROLE ...</code>","ok":true},{"text":"<code>GRANT SELECT ON SCHEMA analitica TO ROLE ...</code>","ok":false},{"text":"<code>GRANT USAGE ON TABLE *</code>","ok":false},{"text":"<code>GRANT SELECT ON FUTURE TABLES IN SCHEMA ...</code>","ok":false}],"enunciado":"<p>¿Cómo das lectura a todas las tablas existentes de un esquema?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-grants-ej3","opciones":[{"text":"Sí, siempre","ok":false},{"text":"Solo si se dio GRANT SELECT ON FUTURE TABLES (o se le da permiso a esa tabla)","ok":true},{"text":"Solo después de un SHOW GRANTS","ok":false},{"text":"Sí, porque tiene USAGE en el esquema","ok":false}],"enunciado":"<p>Mañana se crea una tabla nueva en analitica. ¿La puede leer el analista?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-grants-ej4","opciones":[{"text":"Por falta de warehouse","ok":false},{"text":"Porque el rol solo tiene SELECT, no DELETE","ok":true},{"text":"Porque la tabla no existe","ok":false},{"text":"Por un error de sintaxis","ok":false}],"enunciado":"<p>¿Por qué falló el DELETE del analista?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true}]},"snowflake-paso-a-paso-costos-y-resource-monitors":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Un tope en la tarjeta</div>\n\n<p>Un resource monitor es un tope en la tarjeta del warehouse: avisa cuando llegas al 80 % del presupuesto del mes y, al 100 %, deja de aceptar consultas nuevas. Así una consulta mal escrita no consume el mes en una noche.</p>\n</div>\n\n\n<h2>Paso 1 — Qué se paga</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Concepto</th>\n<th>Cómo se cobra</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Cómputo</strong> (warehouses)</td>\n<td>Créditos por segundo encendido, según el tamaño. Suele ser la mayor parte</td>\n</tr>\n<tr>\n<td><strong>Almacenamiento</strong></td>\n<td>Por TB al mes, incluido Time Travel y Fail-safe</td>\n</tr>\n<tr>\n<td><strong>Servicios en la nube</strong></td>\n<td>Solo si superan el 10 % del cómputo diario</td>\n</tr>\n<tr>\n<td><strong>Funciones serverless</strong></td>\n<td>Snowpipe, tareas serverless, clustering automático: créditos propios</td>\n</tr>\n</tbody></table></div>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s19-creditos.webp\" alt=\"Créditos consumidos en la práctica (1) y el costo de cada tamaño si se usa una hora por día durante un mes (2)\" loading=\"lazy\"><figcaption>Créditos consumidos en la práctica (1) y el costo de cada tamaño si se usa una hora por día durante un mes (2)</figcaption></figure>\n\n\n<h2>Paso 2 — Un resource monitor</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE ROLE ACCOUNTADMIN;\nCREATE RESOURCE MONITOR limite_mensual\n  WITH CREDIT_QUOTA = 50\n  FREQUENCY = MONTHLY\n  START_TIMESTAMP = IMMEDIATELY\n  TRIGGERS ON 80 PERCENT DO NOTIFY\n           ON 100 PERCENT DO SUSPEND;\nALTER WAREHOUSE analisis_wh SET RESOURCE_MONITOR = limite_mensual;\nSHOW RESOURCE MONITORS;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s19-monitor.webp\" alt=\"El resource monitor (1) - cuota de 50 créditos, usados y restantes, asignado a un warehouse (2)\" loading=\"lazy\"><figcaption>El resource monitor (1) - cuota de 50 créditos, usados y restantes, asignado a un warehouse (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Acción</th>\n<th>Qué hace</th>\n</tr>\n</thead><tbody><tr>\n<td><code>DO NOTIFY</code></td>\n<td>Avisa por correo a los administradores</td>\n</tr>\n<tr>\n<td><code>DO SUSPEND</code></td>\n<td>Suspende el warehouse cuando terminan las consultas en curso</td>\n</tr>\n<tr>\n<td><code>DO SUSPEND_IMMEDIATE</code></td>\n<td>Lo suspende ya, cancelando lo que esté corriendo</td>\n</tr>\n</tbody></table></div>\n<p>Solo <strong>ACCOUNTADMIN</strong> puede crear resource monitors y asignarlos.</p>\n<h2>Paso 3 — Mirar el consumo en una cuenta real</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s19-cost-management.webp\" alt=\"Cost Management no está simulado en la práctica\" loading=\"lazy\"><figcaption>Cost Management no está simulado en la práctica</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Dónde</th>\n<th>Qué muestra</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Admin → Cost Management</strong></td>\n<td>Consumo por día, warehouse y servicio, presupuestos y alertas</td>\n</tr>\n<tr>\n<td><code>SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY</code></td>\n<td>Créditos por warehouse y hora, para consultar con SQL</td>\n</tr>\n<tr>\n<td><code>SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY</code></td>\n<td>Qué consultas usaron más tiempo de warehouse</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Monitor sin asignar.</strong> Creado pero no asignado a ningún warehouse (ni a la cuenta), no controla nada.</li>\n<li><strong>Solo avisos.</strong> Si nadie lee los correos, un aviso no frena el gasto; agrega una acción de suspensión.</li>\n<li><strong>Mirar solo el cómputo.</strong> El almacenamiento (incluido Time Travel y Fail-safe) y los servicios serverless también suman.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Sabes qué se paga en Snowflake.</li>\n<li>Creaste y asignaste un resource monitor.</li>\n<li>Sabes dónde se mira el consumo real.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-costos-y-resource-monitors-ej1","opciones":[{"text":"El cómputo de los warehouses","ok":true},{"text":"El almacenamiento de las hojas SQL","ok":false},{"text":"Las hojas SQL","ok":false},{"text":"El Marketplace","ok":false}],"enunciado":"<p>¿Qué suele ser la mayor parte de la factura de Snowflake?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-costos-y-resource-monitors-ej2","opciones":[{"text":"Cualquier rol con USAGE en el warehouse","ok":false},{"text":"SYSADMIN","ok":false},{"text":"ACCOUNTADMIN","ok":true},{"text":"PUBLIC","ok":false}],"enunciado":"<p>¿Quién puede crear un resource monitor?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-costos-y-resource-monitors-ej3","opciones":[{"text":"Borra el warehouse","ok":false},{"text":"Suspende el warehouse al llegar a la cuota, después de terminar lo que está corriendo","ok":true},{"text":"Avisa por correo nada más","ok":false},{"text":"Cancela al instante todas las consultas en curso","ok":false}],"enunciado":"<p>¿Qué hace ON 100 PERCENT DO SUSPEND?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-costos-y-resource-monitors-ej4","opciones":[{"text":"INFORMATION_SCHEMA.TABLES","ok":false},{"text":"SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY","ok":true},{"text":"PUBLIC.CREDITOS","ok":false},{"text":"SHOW TABLES","ok":false}],"enunciado":"<p>¿Qué vista usas para ver créditos por warehouse con SQL?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true}]},"snowflake-paso-a-paso-proyecto-acceso-para-analistas":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El objetivo</div>\n\n<p>Lucía: <em>&quot;Comercial necesita leer <code>analitica</code> todos los días, incluidas las tablas que agreguemos, sin poder escribir ni ver <code>raw</code>, y sin pasar de 50 créditos al mes.&quot;</em></p>\n</div>\n\n\n<h2>Criterio de aceptación</h2>\n<ul>\n<li>Rol <code>analista_ventas</code> con USAGE en <code>analisis_wh</code>, en <code>tienda_dev</code> y en <code>tienda_dev.analitica</code>.</li>\n<li>SELECT en todas las tablas actuales <strong>y futuras</strong> de <code>analitica</code>.</li>\n<li>Ningún permiso en <code>raw</code>.</li>\n<li><code>analisis_wh</code> con el resource monitor <code>limite_mensual</code> (50 créditos, aviso al 80 %, suspensión al 100 %).</li>\n<li>Una prueba que funciona (SELECT en <code>analitica</code>) y dos que fallan (DELETE en <code>analitica</code>, SELECT en <code>raw</code>).</li>\n</ul>\n<h2>Cómo se ve terminado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s20-roles.webp\" alt=\"El rol ANALISTA_VENTAS (1) y sus permisos otorgados (2)\" loading=\"lazy\"><figcaption>El rol ANALISTA_VENTAS (1) y sus permisos otorgados (2)</figcaption></figure>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s20-historial.webp\" alt=\"Query History - las pruebas con el rol analista_ventas: la consulta que funciona y el DELETE que falla\" loading=\"lazy\"><figcaption>Query History - las pruebas con el rol analista_ventas: la consulta que funciona y el DELETE que falla</figcaption></figure>\n\n\n<details><summary>💡 Solución comentada</summary>\n\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">USE ROLE SECURITYADMIN;\nCREATE ROLE IF NOT EXISTS analista_ventas;\nGRANT USAGE ON WAREHOUSE analisis_wh TO ROLE analista_ventas;\nGRANT USAGE ON DATABASE tienda_dev TO ROLE analista_ventas;\nGRANT USAGE ON SCHEMA tienda_dev.analitica TO ROLE analista_ventas;\nGRANT SELECT ON ALL TABLES IN SCHEMA tienda_dev.analitica TO ROLE analista_ventas;\nGRANT SELECT ON FUTURE TABLES IN SCHEMA tienda_dev.analitica TO ROLE analista_ventas;\nGRANT ROLE analista_ventas TO ROLE SYSADMIN;   -- buena práctica: la jerarquía queda bajo SYSADMIN\n\nUSE ROLE ACCOUNTADMIN;\nCREATE RESOURCE MONITOR IF NOT EXISTS limite_mensual WITH CREDIT_QUOTA = 50 FREQUENCY = MONTHLY\n  START_TIMESTAMP = IMMEDIATELY TRIGGERS ON 80 PERCENT DO NOTIFY ON 100 PERCENT DO SUSPEND;\nALTER WAREHOUSE analisis_wh SET RESOURCE_MONITOR = limite_mensual;\n\n-- pruebas\nUSE ROLE analista_ventas;\nSELECT COUNT(*) FROM tienda_dev.analitica.pedidos_actuales;   -- funciona\nDELETE FROM tienda_dev.analitica.pedidos_actuales;            -- falla: sin DELETE\nSELECT COUNT(*) FROM tienda_dev.raw.pedidos_staging;          -- falla: sin USAGE en raw</code></pre>\n<p><strong>Decisiones a defender:</strong></p>\n<ul>\n<li>Un <strong>warehouse por equipo</strong> permite saber quién gasta y ponerle un presupuesto propio.</li>\n<li><strong>FUTURE TABLES</strong> evita que cada tabla nueva requiera un ticket de permisos.</li>\n<li>Las pruebas <strong>negativas</strong> (lo que no debe poder hacer) son tan importantes como las positivas.</li>\n<li>Con Power BI, la conexión usa un usuario de servicio con este mismo rol.</details></li>\n</ul>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Probar solo lo permitido.</strong> Las pruebas negativas (un <code>DELETE</code> o leer <code>raw</code>) son las que muestran que el rol está bien cerrado.</li>\n<li><strong>Olvidar FUTURE TABLES.</strong> El rol funciona hoy y falla con la próxima tabla.</li>\n<li><strong>Compartir el warehouse de ingeniería.</strong> Sin warehouse propio no puedes medir ni limitar el gasto de comercial.</li>\n</ul>\n</div>\n\n\n<h2>Lo que aprendiste en el nivel 5</h2>\n<ul>\n<li>Roles del sistema y jerarquía.</li>\n<li>GRANT, FUTURE GRANTS y REVOKE.</li>\n<li>Costos y resource monitors.</li>\n</ul>\n<p>En el nivel 6: buenas prácticas, las funciones de plataforma (Snowpipe, streams, tasks, dynamic tables) y el paso a Snowflake real.</p>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-acceso-para-analistas-ej1","opciones":[{"text":"Porque Snowflake lo exige","ok":false},{"text":"Para saber cuánto gasta ese equipo y ponerle su presupuesto","ok":true},{"text":"Porque los warehouses no se comparten","ok":false},{"text":"Para que comercial use la caché de ingeniería","ok":false}],"enunciado":"<p>¿Por qué un warehouse propio para comercial?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-acceso-para-analistas-ej2","opciones":[{"text":"No dándole USAGE en el esquema raw","ok":true},{"text":"Borrando raw","ok":false},{"text":"Con un resource monitor sobre raw","ok":false},{"text":"No se puede","ok":false}],"enunciado":"<p>¿Cómo te aseguras de que el rol no ve raw?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-acceso-para-analistas-ej3","opciones":[{"text":"Para medir cuánto tarda cada consulta","ok":false},{"text":"Para comprobar que el rol NO puede hacer lo que no debe","ok":true},{"text":"Para probar el rol con datos falsos","ok":false},{"text":"Para borrar datos","ok":false}],"enunciado":"<p>¿Para qué sirven las pruebas negativas?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-acceso-para-analistas-ej4","opciones":[{"text":"Para que la jerarquía de roles propios quede bajo SYSADMIN y pueda administrar sus objetos","ok":true},{"text":"Para que el analista sea administrador","ok":false},{"text":"Porque es obligatorio para leer","ok":false},{"text":"No tiene sentido","ok":false}],"enunciado":"<p>¿Por qué se asigna analista_ventas a SYSADMIN?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true}]},"snowflake-paso-a-paso-buenas-practicas":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Elegir bien qué cajas abrir</div>\n\n<p>Snowflake guarda cada tabla en muchas cajitas (micro-particiones) con una etiqueta que dice el rango de valores de adentro. Si filtras por una columna bien ordenada, puede descartar cajas sin abrirlas. Nombrar solo las columnas necesarias es abrir solo los compartimentos que usas.</p>\n</div>\n\n\n<h2>Paso 1 — Warehouses</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE TRANSIENT TABLE pedidos_tmp AS SELECT * FROM pedidos_staging;\nALTER WAREHOUSE analisis_wh SET AUTO_SUSPEND = 60;\nSHOW WAREHOUSES;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s21-practicas.webp\" alt=\"Una tabla transitoria para datos recargables y el warehouse con auto suspend de 60 segundos (1); SHOW WAREHOUSES lo confirma (2)\" loading=\"lazy\"><figcaption>Una tabla transitoria para datos recargables y el warehouse con auto suspend de 60 segundos (1); SHOW WAREHOUSES lo confirma (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Práctica</th>\n<th>Por qué</th>\n</tr>\n</thead><tbody><tr>\n<td>Un warehouse por tipo de carga (carga, transformación, BI)</td>\n<td>No se pisan y se sabe quién gasta</td>\n</tr>\n<tr>\n<td><code>AUTO_SUSPEND</code> de 60 segundos (o el mínimo que tolere tu caché)</td>\n<td>Un warehouse encendido sin consultas es dinero tirado</td>\n</tr>\n<tr>\n<td>Empezar en X-Small y subir si hace falta</td>\n<td>Es fácil agrandar; lo caro es no medir</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — Las cachés</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Caché</th>\n<th>Qué guarda</th>\n<th>Cuánto dura</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Resultados</strong></td>\n<td>El resultado de una consulta idéntica sobre datos que no cambiaron</td>\n<td>24 horas; no usa warehouse</td>\n</tr>\n<tr>\n<td><strong>Disco local del warehouse</strong></td>\n<td>Los datos leídos recientemente</td>\n<td>Mientras el warehouse no se suspenda</td>\n</tr>\n<tr>\n<td><strong>Metadatos</strong></td>\n<td>Conteos, mínimos y máximos por micro-partición</td>\n<td>Siempre (<code>COUNT(*)</code> sin filtro sale de aquí)</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 3 — Micro-particiones y poda</h2>\n<p>Snowflake guarda cada tabla en <strong>micro-particiones</strong> de unos 50 a 500 MB sin comprimir, y sabe el mínimo y el máximo de cada columna en cada una. Un <code>WHERE fecha = &#39;2026-11-14&#39;</code> lee solo las particiones que pueden contener esa fecha: eso es la <strong>poda</strong> (<em>pruning</em>).</p>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Situación</th>\n<th>Qué hacer</th>\n</tr>\n</thead><tbody><tr>\n<td>Tablas chicas o medianas</td>\n<td>Nada: el orden de carga suele alcanzar</td>\n</tr>\n<tr>\n<td>Tablas de varios TB filtradas siempre por la misma columna, con poca poda</td>\n<td>Una <strong>clave de clustering</strong>: <code>ALTER TABLE ventas CLUSTER BY (fecha);</code> (tiene costo de mantenimiento)</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 4 — SQL que ahorra</h2>\n<ul>\n<li><strong>No <code>SELECT *</code></strong>: Snowflake guarda por columnas, y leer 3 columnas de 80 es mucho más barato.</li>\n<li>Filtrar por las columnas que podan (fechas) y con <code>LIMIT</code> al explorar.</li>\n<li><code>TRANSIENT</code> para staging y tablas intermedias que se pueden recargar: sin Fail-safe, menos almacenamiento.</li>\n<li>Vistas para el negocio en lugar de copias de tablas.</li>\n</ul>\n<h2>Paso 5 — Lista de revisión</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Cada equipo o proceso con su warehouse y su resource monitor.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Auto suspend corto en todos los warehouses.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Roles de mínimo privilegio; nadie trabaja con ACCOUNTADMIN.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Staging en tablas transitorias.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Cargas con MERGE idempotente.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Objetos creados con scripts versionados (Terraform, Snowflake CLI, dbt), no a mano.</li>\n</ul>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Clustering en todas las tablas.</strong> Mantenerlo consume créditos; solo vale en tablas muy grandes con poca poda.</li>\n<li><strong>Funciones sobre la columna del filtro.</strong> <code>WHERE YEAR(fecha) = 2024</code> impide descartar micro-particiones; filtra por rango de fechas.</li>\n<li><strong>Warehouses que nunca se apagan.</strong> AUTO_SUSPEND corto en todos, sobre todo en los de análisis.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Sabes dimensionar y apagar warehouses.</li>\n<li>Entiendes cachés, poda y clustering.</li>\n<li>Tienes una lista de revisión.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-buenas-practicas-ej1","opciones":[{"text":"1 minuto","ok":false},{"text":"24 horas, si los datos no cambiaron","ok":true},{"text":"7 días","ok":false},{"text":"Para siempre","ok":false}],"enunciado":"<p>¿Cuánto dura la caché de resultados de Snowflake?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-buenas-practicas-ej2","opciones":[{"text":"Leer solo las particiones que pueden tener filas que cumplen el filtro","ok":true},{"text":"Borrar particiones viejas","ok":false},{"text":"Comprimir la tabla","ok":false},{"text":"Agrupar consultas parecidas en el mismo warehouse","ok":false}],"enunciado":"<p>¿Qué es la poda de micro-particiones?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-buenas-practicas-ej3","opciones":[{"text":"En todas las tablas","ok":false},{"text":"En tablas muy grandes filtradas siempre por la misma columna y con poca poda","ok":true},{"text":"En tablas de 100 filas","ok":false},{"text":"En tablas que se recargan completas todos los días","ok":false}],"enunciado":"<p>¿Cuándo vale la pena una clave de clustering?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-buenas-practicas-ej4","opciones":[{"text":"Porque desactiva la poda de micro-particiones","ok":false},{"text":"Porque guarda por columnas y leer todas cuesta más que leer las necesarias","ok":true},{"text":"Porque no usa caché nunca","ok":false},{"text":"No cuesta más: Snowflake guarda por filas","ok":false}],"enunciado":"<p>¿Por qué SELECT * cuesta más en Snowflake?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true}]},"snowflake-paso-a-paso-snowpipe-streams-tasks-y-mas":{"html":"<div class=\"callout callout-nota\"><div class=\"callout-title\">📝 En la práctica</div>\n\n<p>Estas funciones no están simuladas: la práctica te muestra qué son. El SQL de esta lección es el de Snowflake real.</p>\n</div>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s22-tareas.webp\" alt=\"Task History - las ejecuciones de las tasks programadas (no simulado en la práctica)\" loading=\"lazy\"><figcaption>Task History - las ejecuciones de las tasks programadas (no simulado en la práctica)</figcaption></figure>\n\n\n<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Una línea de producción automática</div>\n\n<p>Snowpipe es la cinta que recibe cada archivo apenas llega; un stream es el cuaderno donde se anota qué filas cambiaron; una task es el reloj que corre un SQL a horario; una dynamic table es una tabla que se mantiene sola a partir de una consulta. Juntas arman una línea que funciona sin que nadie apriete botones.</p>\n</div>\n\n\n<h2>Paso 1 — Snowpipe: carga continua</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE PIPE raw.pipe_pedidos AUTO_INGEST = TRUE AS\nCOPY INTO raw.pedidos_staging FROM @ventas_s3 FILE_FORMAT = (TYPE = CSV SKIP_HEADER = 1);</code></pre>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>COPY INTO</th>\n<th>Snowpipe</th>\n</tr>\n</thead><tbody><tr>\n<td>Lo ejecutas tú (o un orquestador) con un warehouse</td>\n<td>Se dispara solo cuando llega un archivo al bucket (por un evento de la nube)</td>\n</tr>\n<tr>\n<td>Por lotes</td>\n<td>Continuo, en minutos</td>\n</tr>\n<tr>\n<td>Paga el warehouse</td>\n<td>Cómputo serverless de Snowflake</td>\n</tr>\n</tbody></table></div>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s22-copy.webp\" alt=\"Copy History - el historial de cargas archivo por archivo (no simulado en la práctica)\" loading=\"lazy\"><figcaption>Copy History - el historial de cargas archivo por archivo (no simulado en la práctica)</figcaption></figure>\n\n\n<h2>Paso 2 — Streams y tasks</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">-- un stream registra qué filas se insertaron, actualizaron o borraron desde la última vez que se leyó\nCREATE STREAM raw.cambios_pedidos ON TABLE raw.pedidos_staging;\n\n-- una task ejecuta SQL con un horario; solo corre si el stream tiene datos\nCREATE TASK analitica.aplicar_pedidos\n  WAREHOUSE = analisis_wh\n  SCHEDULE = '15 MINUTE'\n  WHEN SYSTEM$STREAM_HAS_DATA('raw.cambios_pedidos')\nAS\n  MERGE INTO analitica.pedidos_actuales t\n  USING raw.cambios_pedidos s ON t.pedido_id = s.pedido_id\n  WHEN MATCHED THEN UPDATE SET total = s.total\n  WHEN NOT MATCHED THEN INSERT (pedido_id, cliente_id, fecha, canal, total)\n                        VALUES (s.pedido_id, s.cliente_id, s.fecha, s.canal, s.total);\n\nALTER TASK analitica.aplicar_pedidos RESUME;   -- las tasks se crean suspendidas</code></pre>\n<h2>Paso 3 — Dynamic tables</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE DYNAMIC TABLE analitica.ventas_diarias\n  TARGET_LAG = '1 hour'\n  WAREHOUSE = analisis_wh\nAS\n  SELECT fecha, canal, SUM(total) AS ventas\n  FROM analitica.pedidos_actuales\n  GROUP BY fecha, canal;</code></pre>\n<p>Declaras <strong>qué</strong> resultado quieres y <strong>cuán atrasado</strong> puede estar (<code>TARGET_LAG</code>); Snowflake se encarga de refrescarla, de forma incremental cuando puede. Reemplaza muchas combinaciones de stream + task.</p>\n<h2>Paso 4 — Más de la plataforma</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Función</th>\n<th>Qué es</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Snowpark</strong></td>\n<td>Escribir transformaciones en Python, Java o Scala que corren dentro de Snowflake</td>\n</tr>\n<tr>\n<td><strong>Cortex AI</strong></td>\n<td>Funciones de IA en SQL (resumir, clasificar, traducir, búsqueda semántica)</td>\n</tr>\n<tr>\n<td><strong>Secure Data Sharing</strong></td>\n<td>Compartir tablas con otra cuenta <strong>sin copiarlas</strong>; la base del Marketplace</td>\n</tr>\n<tr>\n<td><strong>Streamlit in Snowflake</strong></td>\n<td>Apps de datos en Python dentro de la cuenta</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 5 — ¿Dentro de Snowflake o con un orquestador?</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Si…</th>\n<th>Conviene</th>\n</tr>\n</thead><tbody><tr>\n<td>Todo el flujo es SQL dentro de Snowflake</td>\n<td>Tasks o dynamic tables</td>\n</tr>\n<tr>\n<td>El flujo mezcla Snowflake con APIs, otros sistemas o avisos</td>\n<td>Un orquestador como <a href=\"#/m/airflow-paso-a-paso\">Airflow</a></td>\n</tr>\n<tr>\n<td>El equipo transforma con modelos versionados y pruebas</td>\n<td>dbt (puede generar dynamic tables)</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Leer un stream y no consumirlo en una transacción DML.</strong> El stream avanza solo cuando sus filas se usan en un INSERT, MERGE u otra escritura que confirma.</li>\n<li><strong>Tasks que quedan suspendidas.</strong> Una task recién creada está suspendida; hay que hacer <code>ALTER TASK ... RESUME</code>.</li>\n<li><strong>Orquestar dentro de Snowflake lo que depende de sistemas externos.</strong> Si hay APIs, avisos o pasos en otros servicios, conviene un orquestador.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Conoces Snowpipe, streams, tasks y dynamic tables.</li>\n<li>Ubicas Snowpark, Cortex y Data Sharing.</li>\n<li>Sabes cuándo usar un orquestador.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-snowpipe-streams-tasks-y-mas-ej1","opciones":[{"text":"Snowpipe carga solo archivos JSON","ok":false},{"text":"Snowpipe se dispara solo al llegar el archivo y usa cómputo serverless","ok":true},{"text":"Snowpipe no carga CSV","ok":false},{"text":"Snowpipe necesita ACCOUNTADMIN para cada archivo","ok":false}],"enunciado":"<p>¿En qué se diferencia Snowpipe de un COPY INTO programado?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-snowpipe-streams-tasks-y-mas-ej2","opciones":[{"text":"Las filas que cambiaron en la tabla desde la última vez que se leyó","ok":true},{"text":"Toda la tabla","ok":false},{"text":"Las consultas que se ejecutaron sobre la tabla","ok":false},{"text":"El historial de consultas","ok":false}],"enunciado":"<p>¿Qué devuelve un stream?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-snowpipe-streams-tasks-y-mas-ej3","opciones":[{"text":"El tamaño del warehouse","ok":false},{"text":"Cuánto puede atrasarse la tabla respecto de sus fuentes","ok":true},{"text":"Cada cuántos minutos se borra la tabla","ok":false},{"text":"Quién puede leerla","ok":false}],"enunciado":"<p>¿Qué indica TARGET_LAG en una dynamic table?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-snowpipe-streams-tasks-y-mas-ej4","opciones":[{"text":"Solo tasks, encadenadas con AFTER","ok":false},{"text":"Un orquestador como Airflow","ok":true},{"text":"Una dynamic table","ok":false},{"text":"Un stream","ok":false}],"enunciado":"<p>El flujo llama a una API, carga en Snowflake y avisa por Slack. ¿Qué conviene?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true}]},"snowflake-paso-a-paso-de-la-practica-a-snowflake-real":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Del simulador al avión</div>\n\n<p>Lo que practicaste (warehouses, roles, COPY INTO, MERGE, Time Travel) funciona igual en una cuenta real. Lo que cambia es que los créditos se pagan y que hay más gente con distintos roles: por eso lo primero es poner topes y separar permisos.</p>\n</div>\n\n\n<h2>Paso 1 — Qué cambia</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>En la práctica</th>\n<th>En Snowflake real</th>\n</tr>\n</thead><tbody><tr>\n<td>El SQL corre en tu navegador sobre datos chicos</td>\n<td>Corre en la nube sobre TB, con el optimizador de Snowflake</td>\n</tr>\n<tr>\n<td>Los créditos son estimados</td>\n<td>Los créditos se facturan</td>\n</tr>\n<tr>\n<td>Sin usuarios ni MFA</td>\n<td>Usuarios, MFA, políticas de red y SSO</td>\n</tr>\n<tr>\n<td>Marketplace, Notebooks, Task History no simulados</td>\n<td>Disponibles según la edición</td>\n</tr>\n</tbody></table></div>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s23-marketplace.webp\" alt=\"Marketplace - en Snowflake real, datos de terceros compartidos sin copiarlos\" loading=\"lazy\"><figcaption>Marketplace - en Snowflake real, datos de terceros compartidos sin copiarlos</figcaption></figure>\n\n\n<p>Lo que <strong>no</strong> cambia: el SQL, los objetos, los roles y las decisiones de diseño.</p>\n<h2>Paso 2 — Una prueba gratuita</h2>\n<ol>\n<li>En el sitio de Snowflake, <strong>Start for free</strong>: la prueba dura <strong>30 días</strong> e incluye créditos de uso (al escribir esto, USD 400).</li>\n<li>Elige <strong>edición</strong> (Standard, Enterprise, Business Critical) y <strong>nube y región</strong>. Para aprender alcanza Standard o Enterprise, en la región más cercana.</li>\n<li>Activa <strong>MFA</strong> en tu usuario el primer día.</li>\n<li>Crea un warehouse X-Small con auto suspend de 60 segundos y un resource monitor antes de cargar nada.</li>\n</ol>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s23-cuenta.webp\" alt=\"El menú del usuario - cuenta, roles, apariencia y documentación\" loading=\"lazy\"><figcaption>El menú del usuario - cuenta, roles, apariencia y documentación</figcaption></figure>\n\n\n<h2>Paso 3 — Conectar herramientas</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Herramienta</th>\n<th>Cómo se conecta</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Snowflake CLI</strong> (<code>snow</code>)</td>\n<td>Desde la terminal: ejecutar SQL, subir archivos, desplegar apps. <code>snow sql -q &quot;SELECT CURRENT_VERSION()&quot;</code></td>\n</tr>\n<tr>\n<td><strong>Conector de Python</strong></td>\n<td><code>snowflake-connector-python</code> o Snowpark</td>\n</tr>\n<tr>\n<td><strong>Power BI / Tableau</strong></td>\n<td>Conector nativo de Snowflake con un rol de lectura (proyecto 5)</td>\n</tr>\n<tr>\n<td><strong>dbt</strong></td>\n<td><code>dbt-snowflake</code>, con un rol y warehouse de transformación</td>\n</tr>\n<tr>\n<td><strong>Airflow</strong></td>\n<td>Provider <code>apache-airflow-providers-snowflake</code> y una conexión <code>snowflake_default</code></td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-cuidado\"><div class=\"callout-title\">⚠️ Usuarios de servicio</div>\n\n<p>Para herramientas y procesos automáticos, crea <strong>usuarios de servicio</strong> con autenticación por <strong>par de claves</strong> (key-pair) u OAuth, un rol propio y un warehouse propio. Nunca uses tu usuario personal ni pongas contraseñas en el código.</p>\n</div>\n\n\n<h2>Paso 4 — Tu primera semana</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Pedir un rol de desarrollo (no ACCOUNTADMIN) y un warehouse propio.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Recorrer las bases y esquemas y entender qué capa es cada una.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Leer el Query History de los procesos nocturnos.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Revisar quién tiene qué con <code>SHOW GRANTS</code>.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Hacer tus pruebas en un clon, nunca en producción.</li>\n</ul>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 Capturas</div>\n\n<p>Si compartes capturas de una cuenta real, difumina el nombre de la cuenta, la URL, los usuarios y cualquier dato de clientes.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Probar con un warehouse grande.</strong> En la prueba gratuita los créditos se acaban rápido; empieza con X-Small y auto suspend corto.</li>\n<li><strong>Conectar herramientas con tu usuario personal.</strong> dbt o Airflow usan un usuario de servicio con key-pair u OAuth y un rol propio.</li>\n<li><strong>Usar ACCOUNTADMIN para el trabajo diario.</strong> Úsalo para facturación y monitores, y trabaja con roles propios.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Sabes qué cambia en Snowflake real.</li>\n<li>Sabes abrir una prueba de forma segura.</li>\n<li>Sabes conectar herramientas sin exponer credenciales.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-de-la-practica-a-snowflake-real-ej1","opciones":[{"text":"7 días","ok":false},{"text":"30 días","ok":true},{"text":"1 año","ok":false},{"text":"90 días","ok":false}],"enunciado":"<p>¿Cuánto dura la prueba gratuita de Snowflake?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-de-la-practica-a-snowflake-real-ej2","opciones":[{"text":"Tu contraseña personal","ok":false},{"text":"Par de claves (key-pair) u OAuth, con un rol propio","ok":true},{"text":"Usuario y contraseña compartidos por el equipo","ok":false},{"text":"La contraseña de ACCOUNTADMIN","ok":false}],"enunciado":"<p>¿Qué autenticación conviene para un usuario de servicio (por ejemplo, dbt o Airflow)?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-de-la-practica-a-snowflake-real-ej3","opciones":[{"text":"Snowflake CLI (snow)","ok":true},{"text":"Excel","ok":false},{"text":"Power BI","ok":false},{"text":"Snowsight, porque no existe una CLI","ok":false}],"enunciado":"<p>¿Con qué herramienta ejecutas SQL de Snowflake desde la terminal?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-de-la-practica-a-snowflake-real-ej4","opciones":[{"text":"Un warehouse 4X-Large","ok":false},{"text":"Un warehouse X-Small con auto suspend corto y un resource monitor","ok":true},{"text":"Un usuario por cada herramienta, con ACCOUNTADMIN","ok":false},{"text":"Una base con Time Travel de 90 días","ok":false}],"enunciado":"<p>¿Qué es lo primero que conviene crear en una cuenta de prueba?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true}]},"snowflake-paso-a-paso-proyecto-final-warehouse-tienda-andina":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El encargo</div>\n\n<p>Gerencia de Tienda Andina: <em>&quot;Queremos los pedidos y los eventos de la web en Snowflake, actualizados cada día, con un tablero para comercial. Que nadie pueda romper los datos, que se pueda recuperar si pasa algo, y que sepamos cuánto cuesta.&quot;</em></p>\n</div>\n\n\n<h2>Requisitos</h2>\n<p><strong>Entorno</strong></p>\n<ol>\n<li>Base <code>tienda_dev</code> con esquemas <code>raw</code> y <code>analitica</code>, creados con un script que se pueda correr dos veces.</li>\n<li>Warehouses <code>carga_wh</code> y <code>analisis_wh</code>, X-Small, con auto suspend de 60 segundos.</li>\n</ol>\n<p><strong>Carga</strong>\n3. Stage <code>carga_pedidos</code> y <code>raw.pedidos_staging</code> cargada con COPY INTO desde al menos dos archivos de días distintos.\n4. <code>raw.eventos_web</code> con eventos JSON y una vista <code>analitica.items_vendidos</code> hecha con FLATTEN.\n5. <code>analitica.pedidos_actuales</code> actualizada con un MERGE deduplicado e idempotente.</p>\n<p><strong>Operación y gobierno</strong>\n6. Un procedimiento escrito para recuperar <code>pedidos_actuales</code> ante un error (Time Travel con el Query ID).\n7. Un clon <code>tienda_qa</code> para probar cambios.\n8. Rol <code>analista_ventas</code> de solo lectura sobre <code>analitica</code>, con tablas futuras.\n9. Resource monitor mensual en <code>analisis_wh</code>.</p>\n<h2>Cómo se ve terminado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s24-arbol.webp\" alt=\"TIENDA_DEV con raw (staging, eventos, stage, transitoria) y analitica (pedidos_actuales, ventas_por_canal)\" loading=\"lazy\"><figcaption>TIENDA_DEV con raw (staging, eventos, stage, transitoria) y analitica (pedidos_actuales, ventas_por_canal)</figcaption></figure>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/snowflake/s24-warehouses.webp\" alt=\"Los warehouses con su estado, tamaño, auto suspend y créditos consumidos\" loading=\"lazy\"><figcaption>Los warehouses con su estado, tamaño, auto suspend y créditos consumidos</figcaption></figure>\n\n\n<h2>Entregable: el documento de una página</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Sección</th>\n<th>Qué responde</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Arquitectura</strong></td>\n<td>Diagrama: archivos → stage → raw → MERGE → analitica → Power BI</td>\n</tr>\n<tr>\n<td><strong>Carga</strong></td>\n<td>Por qué COPY INTO + MERGE, cómo se evita duplicar</td>\n</tr>\n<tr>\n<td><strong>Recuperación</strong></td>\n<td>Qué haces si alguien borra o actualiza mal (Time Travel, UNDROP, clon)</td>\n</tr>\n<tr>\n<td><strong>Seguridad</strong></td>\n<td>Roles, qué ve cada uno y cómo se conectan las herramientas</td>\n</tr>\n<tr>\n<td><strong>Costos</strong></td>\n<td>Warehouses, horas estimadas por día, créditos por mes y el resource monitor</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Diseñar sin pensar quién consulta qué.</strong> Los roles, esquemas y warehouses salen de cómo trabaja cada equipo.</li>\n<li><strong>Dar por buena la carga sin correrla dos veces.</strong> La idempotencia se prueba.</li>\n<li><strong>Documentar la recuperación sin probarla.</strong> Provoca un borrado en un clon y recupéralo siguiendo tus pasos.</li>\n</ul>\n</div>\n\n\n<h2>✅ Rúbrica</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Criterio</th>\n<th>Cumple</th>\n<th>Destaca</th>\n</tr>\n</thead><tbody><tr>\n<td>Entorno</td>\n<td>Base, esquemas y warehouses creados</td>\n<td>Todo en un script versionado e idempotente</td>\n</tr>\n<tr>\n<td>Carga</td>\n<td>COPY INTO y MERGE funcionan</td>\n<td>Deduplicación por fecha de llegada y carga probada dos veces sin cambios</td>\n</tr>\n<tr>\n<td>JSON</td>\n<td>La vista con FLATTEN devuelve un ítem por fila</td>\n<td>Maneja arreglos vacíos con <code>outer =&gt; TRUE</code></td>\n</tr>\n<tr>\n<td>Recuperación</td>\n<td>El procedimiento está escrito</td>\n<td>Lo probaste con un error provocado</td>\n</tr>\n<tr>\n<td>Seguridad</td>\n<td>Rol de solo lectura</td>\n<td>Pruebas positivas y negativas documentadas</td>\n</tr>\n<tr>\n<td>Costos</td>\n<td>Resource monitor activo</td>\n<td>Estimación mensual justificada</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 Para tu portafolio</div>\n\n<p>Sube el script SQL y el documento a un repositorio de GitHub con un README que tenga el diagrama y capturas <strong>de la práctica</strong> o de tu cuenta de prueba, sin datos de terceros. Si te preparas para la certificación <strong>SnowPro Core</strong>, este proyecto cubre buena parte de sus temas: arquitectura, carga, rendimiento, seguridad y costos.</p>\n</div>\n\n\n<h2>Lo que aprendiste en el curso</h2>\n<ul>\n<li><strong>Nivel 1:</strong> qué es Snowflake, Snowsight, hojas SQL y explorar datos.</li>\n<li><strong>Nivel 2:</strong> warehouses, bases, esquemas, tablas y el historial.</li>\n<li><strong>Nivel 3:</strong> stages, COPY INTO, JSON y MERGE.</li>\n<li><strong>Nivel 4:</strong> Time Travel, UNDROP, clones y SQL analítico.</li>\n<li><strong>Nivel 5:</strong> roles, GRANT, costos y resource monitors.</li>\n<li><strong>Nivel 6:</strong> buenas prácticas, automatización y Snowflake real.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-final-warehouse-tienda-andina-ej1","opciones":[{"text":"Usar INSERT con un warehouse dedicado","ok":false},{"text":"COPY INTO que saltea archivos ya cargados y un MERGE deduplicado","ok":true},{"text":"Un warehouse grande","ok":false},{"text":"Borrar todo cada día","ok":false}],"enunciado":"<p>¿Qué hace idempotente la carga del proyecto?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-final-warehouse-tienda-andina-ej2","opciones":[{"text":"UNDROP TABLE (si se borró la tabla) o Time Travel con el Query ID (si se borraron filas)","ok":true},{"text":"Fail-safe","ok":false},{"text":"Un clon de la tabla creado después del borrado","ok":false},{"text":"Pedirle a soporte Fail-safe en el momento","ok":false}],"enunciado":"<p>Alguien borra pedidos_actuales por error. ¿Qué usas primero?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-final-warehouse-tienda-andina-ej3","opciones":[{"text":"Porque uno no alcanza para SQL","ok":false},{"text":"Para que no se pisen y para medir y limitar el costo de cada uno","ok":true},{"text":"Porque Snowflake lo exige","ok":false},{"text":"Porque un warehouse no puede leer dos esquemas","ok":false}],"enunciado":"<p>¿Por qué dos warehouses (carga y análisis)?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"snowflake-paso-a-paso-proyecto-final-warehouse-tienda-andina-ej4","opciones":[{"text":"AZ-900","ok":false},{"text":"SnowPro Core","ok":true},{"text":"PL-300","ok":false},{"text":"AWS SAA","ok":false}],"enunciado":"<p>¿Qué certificación de Snowflake cubre los temas del curso?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true}]}});
